}
#networkCanvas { width: 100%; height: 100%; display: block; }
.canvas-overlay-legend {
    position: absolute; bottom: 12px; right: 12px;
    background: rgba(15, 23, 42, 0.85); border: 1px solid var(--border-color);
    padding: 8px 12px; border-radius: var(--radius-sm); font-size: 11px; display: flex; gap: 12px;
