.event-alert.severity-critical { border-color: var(--rose); background: rgba(239, 68, 68, 0.2); animation: alertpulse-rose 0.5s infinite; }

@keyframes alertpulse {
    0% { border-color: rgba(245, 158, 11, 0.3); box-shadow: 0 0 0; }
    50% { border-color: rgba(245, 158, 11, 1); box-shadow: 0 0 15px rgba(245, 158, 11, 0.5); }
