.action-btn.selected { background: rgba(255,255,255,0.1); box-shadow: inset 0 0 10px rgba(255,255,255,0.05); }
.strategy-icon { margin-right: 10px; font-size: 20px; }
.strategy-options { padding: 12px; background: rgba(0,0,0,0.3); border-radius: 0 0 var(--radius-sm) var(--radius-sm); margin-top: -5px; }

/* Score Popup Modal */
