namespace NexusTwin.Build
{
    public static class BuildPipeline
    {
        [MenuItem("NEXUS-TWIN/Build Standalone Windows")]
        public static void BuildWindows()
        {
            string[] scenes = new string[]
            {
                "Assets/_NexusTwin/Scenes/Gameplay_J1J2J3.unity"
            };

            string buildDir = "c:/Users/Home/Downloads/PROJECTS/NEXUS-TWIN/build/NEXUS-TWIN_Mission01_Windows";
            if (!Directory.Exists(buildDir))
            {
                Directory.CreateDirectory(buildDir);
            }

            string locationPathName = Path.Combine(buildDir, "NEXUS-TWIN.exe");

            BuildPlayerOptions buildPlayerOptions = new BuildPlayerOptions
            {
                scenes = scenes,
                locationPathName = locationPathName,
                target = BuildTarget.StandaloneWindows64,
                options = BuildOptions.None
            };

            Debug.Log($"[BuildPipeline] Starting StandaloneWindows64 build to: {locationPathName}");
            BuildReport report = UnityEditor.BuildPipeline.BuildPlayer(buildPlayerOptions);
            BuildSummary summary = report.summary;

            if (summary.result == BuildResult.Succeeded)
            {
                Debug.Log($"[BuildPipeline] Build SUCCEEDED: {summary.totalSize} bytes, output at {locationPathName}");
            }
            else if (summary.result == BuildResult.Failed)
            {
                Debug.LogError($"[BuildPipeline] Build FAILED with {summary.totalErrors} errors");
            }
        }
    }
}

using UnityEngine;

namespace NexusTwin.Audio
{
    /// <summary>
    /// SoundManager — Procedural and clip-based audio synthesizer for NEXUS-TWIN.
    /// Generates distinct auditory feedback for UI clicks, AI alerts, emergency sirens,
    /// simulation hums, and victory fanfares without requiring external audio assets.
    /// </summary>
    public class SoundManager : MonoBehaviour
    {
        public static SoundManager Instance { get; private set; }

        [Header("Audio Sources")]
        public AudioSource sfxSource;
        public AudioSource sirenSource;
        public AudioSource ambientSource;

        private AudioClip _clickClip;
        private AudioClip _alertClip;
        private AudioClip _approveClip;
        private AudioClip _rejectClip;
        private AudioClip _sirenClip;
        private AudioClip _fanfareClip;

        private void Awake()
        {
            if (Instance != null && Instance != this)
            {
                Destroy(gameObject);
                return;
            }
            Instance = this;
            DontDestroyOnLoad(gameObject);

            InitializeAudioSources();
            GenerateProceduralClips();
        }

        private void InitializeAudioSources()
        {
            sfxSource = gameObject.AddComponent<AudioSource>();
            sfxSource.playOnAwake = false;
            sfxSource.volume = 0.7f;

            sirenSource = gameObject.AddComponent<AudioSource>();
            sirenSource.playOnAwake = false;
            sirenSource.loop = true;
            sirenSource.volume = 0.5f;

            ambientSource = gameObject.AddComponent<AudioSource>();
            ambientSource.playOnAwake = false;
            ambientSource.loop = true;
            ambientSource.volume = 0.25f;
        }

        private AudioClip _ambientClip;
        public bool isMuted = false;

        private void Start()
        {
            PlayAmbient();
        }

        private void Update()
        {
            if (Input.GetKeyDown(KeyCode.M))
            {
                ToggleMute();
            }
        }

        public void ToggleMute()
        {
            isMuted = !isMuted;
            AudioListener.volume = isMuted ? 0f : 1f;
            Debug.Log($"[SoundManager] Audio Mute = {isMuted}");
        }

        private void GenerateProceduralClips()
        {
            _clickClip = CreateTone(880f, 0.08f, 0.5f);        // High crisp click (A5)
            _alertClip = CreateDualTone(587f, 880f, 0.35f);    // Warning chime (D5 + A5)
            _approveClip = CreateChime(new float[] { 523f, 659f, 784f }, 0.4f); // C Major chord
            _rejectClip = CreateTone(220f, 0.25f, 0.6f);       // Low buzz (A3)
            _sirenClip = CreateSiren(0.8f);                    // Modulated emergency siren
            _fanfareClip = CreateChime(new float[] { 523f, 659f, 784f, 1046f }, 0.8f); // Victory chord
            _ambientClip = CreateAmbientDrone(4.0f);            // City rumble
        }

        public void PlayAmbient()
        {
            if (ambientSource != null && _ambientClip != null && !ambientSource.isPlaying)
            {
                ambientSource.clip = _ambientClip;
                ambientSource.Play();
            }
        }

        public void PlayClick()
        {
            if (sfxSource != null && _clickClip != null) sfxSource.PlayOneShot(_clickClip, 0.6f);
        }

        public void PlayAlert()
        {
            if (sfxSource != null && _alertClip != null) sfxSource.PlayOneShot(_alertClip, 0.85f);
        }

        public void PlayApprove()
        {
            if (sfxSource != null && _approveClip != null) sfxSource.PlayOneShot(_approveClip, 0.8f);
        }

        public void PlayReject()
        {
            if (sfxSource != null && _rejectClip != null) sfxSource.PlayOneShot(_rejectClip, 0.7f);
        }

        public void PlayFanfare()
        {
            if (sfxSource != null && _fanfareClip != null) sfxSource.PlayOneShot(_fanfareClip, 0.9f);
        }

        public void StartSiren()
        {
            if (sirenSource != null && _sirenClip != null && !sirenSource.isPlaying)
            {
                sirenSource.clip = _sirenClip;
                sirenSource.Play();
            }
        }

        public void StopSiren()
        {
            if (sirenSource != null && sirenSource.isPlaying)
            {
                sirenSource.Stop();
            }
        }

        // --- Procedural Synthesis Helpers ---

        private AudioClip CreateTone(float frequency, float duration, float volume)
        {
            int sampleRate = 44100;
            int sampleCount = Mathf.CeilToInt(sampleRate * duration);
            float[] samples = new float[sampleCount];

            for (int i = 0; i < sampleCount; i++)
            {
                float t = (float)i / sampleRate;
                float envelope = 1f - (t / duration); // Exponential decay
                samples[i] = Mathf.Sin(2f * Mathf.PI * frequency * t) * envelope * volume;
            }

            AudioClip clip = AudioClip.Create($"Tone_{frequency}", sampleCount, 1, sampleRate, false);
            clip.SetData(samples, 0);
            return clip;
        }

        private AudioClip CreateDualTone(float f1, float f2, float duration)
        {
            int sampleRate = 44100;
            int sampleCount = Mathf.CeilToInt(sampleRate * duration);
            float[] samples = new float[sampleCount];

            for (int i = 0; i < sampleCount; i++)
            {
                float t = (float)i / sampleRate;
                float env = Mathf.Sin(Mathf.PI * (t / duration));
                float wave = (Mathf.Sin(2f * Mathf.PI * f1 * t) + Mathf.Sin(2f * Mathf.PI * f2 * t)) * 0.5f;
                samples[i] = wave * env * 0.6f;
            }

            AudioClip clip = AudioClip.Create("DualTone", sampleCount, 1, sampleRate, false);
            clip.SetData(samples, 0);
            return clip;
        }

        private AudioClip CreateChime(float[] freqs, float duration)
        {
            int sampleRate = 44100;
            int sampleCount = Mathf.CeilToInt(sampleRate * duration);
            float[] samples = new float[sampleCount];

            for (int i = 0; i < sampleCount; i++)
            {
                float t = (float)i / sampleRate;
                float env = 1f - Mathf.Pow(t / duration, 0.7f);
                float wave = 0f;
                for (int f = 0; f < freqs.Length; f++)
                {
                    wave += Mathf.Sin(2f * Mathf.PI * freqs[f] * t);
                }
                samples[i] = (wave / freqs.Length) * env * 0.6f;
            }

            AudioClip clip = AudioClip.Create("Chime", sampleCount, 1, sampleRate, false);
            clip.SetData(samples, 0);
            return clip;
        }

        private AudioClip CreateSiren(float duration)
        {
            int sampleRate = 44100;
            int sampleCount = Mathf.CeilToInt(sampleRate * duration);
            float[] samples = new float[sampleCount];

            for (int i = 0; i < sampleCount; i++)
            {
                float t = (float)i / sampleRate;
                float mod = (Mathf.Sin(2f * Mathf.PI * 1.5f * t) + 1f) * 0.5f;
                float freq = Mathf.Lerp(600f, 1100f, mod);
                samples[i] = Mathf.Sin(2f * Mathf.PI * freq * t) * 0.45f;
            }

            AudioClip clip = AudioClip.Create("Siren", sampleCount, 1, sampleRate, false);
            clip.SetData(samples, 0);
            return clip;
        }

        private AudioClip CreateAmbientDrone(float duration)
        {
            int sampleRate = 44100;
            int sampleCount = Mathf.CeilToInt(sampleRate * duration);
            float[] samples = new float[sampleCount];

            for (int i = 0; i < sampleCount; i++)
            {
                float t = (float)i / sampleRate;
                float noise = (Mathf.Sin(2f * Mathf.PI * 55f * t) + Mathf.Sin(2f * Mathf.PI * 110f * t) * 0.5f) * 0.15f;
                samples[i] = noise;
            }

            AudioClip clip = AudioClip.Create("AmbientDrone", sampleCount, 1, sampleRate, false);
            clip.SetData(samples, 0);
            return clip;
        }
    }
}

using UnityEngine;
using NexusTwin.Data;
using NexusTwin.Core;

namespace NexusTwin.Camera
{
    /// <summary>
    /// StrategicCameraController — 3/4 elevated camera controller for NEXUS-TWIN.
    /// Supports Pan, Zoom, Smooth Orbit, Junction Focus (J1, J2, J3), and Incident Focus.
    /// Per DESIGN_GUIDELINES.md §7-8 and Phase B specifications.
    /// </summary>
    public class StrategicCameraController : MonoBehaviour
    {
        public static StrategicCameraController Instance { get; private set; }

        [Header("Movement Settings")]
        public float panSpeed = 25f;
        public float zoomSpeed = 40f;
        public float minZoomDist = 10f;
        public float maxZoomDist = 120f;
        public float smoothTime = 0.15f;

        [Header("Bounds")]
        public Vector2 xBounds = new Vector2(-150f, 150f);
        public Vector2 zBounds = new Vector2(-200f, 200f);

        [Header("Current Mode")]
        public CameraMode mode = CameraMode.Strategic;

        [Header("Focus Targets")]
        public Transform targetJ1;
        public Transform targetJ2;
        public Transform targetJ3;
        public Transform incidentTarget;

        private Vector3 _targetPosition;
        private float _currentZoom = 45f;
        private Vector3 _velocity = Vector3.zero;

        private void Awake()
        {
            if (Instance != null && Instance != this)
            {
                Destroy(gameObject);
                return;
            }
            Instance = this;
        }

        private void Start()
        {
            _targetPosition = transform.position;
            _currentZoom = transform.position.y;
            EventBus.OnIncidentTriggered += HandleIncidentTriggered;
        }

        private void OnDestroy()
        {
            EventBus.OnIncidentTriggered -= HandleIncidentTriggered;
        }

        private void Update()
        {
            if (mode == CameraMode.IncidentFocus && incidentTarget != null)
            {
                Vector3 desired = new Vector3(incidentTarget.position.x, 30f, incidentTarget.position.z - 25f);
                _targetPosition = Vector3.Lerp(_targetPosition, desired, Time.deltaTime * 3f);
            }
            else
            {
                HandlePan();
                HandleZoom();
                HandleKeyboardShortcuts();
            }

            // Smooth position update
            transform.position = Vector3.SmoothDamp(transform.position, _targetPosition, ref _velocity, smoothTime);
        }

        private void HandlePan()
        {
            float h = Input.GetAxis("Horizontal"); // A/D or Left/Right
            float v = Input.GetAxis("Vertical");   // W/S or Up/Down

            // Right click drag pan
            if (Input.GetMouseButton(1))
            {
                h = -Input.GetAxis("Mouse X") * 2f;
                v = -Input.GetAxis("Mouse Y") * 2f;
            }

            if (Mathf.Abs(h) > 0.01f || Mathf.Abs(v) > 0.01f)
            {
                mode = CameraMode.Strategic;
                Vector3 forward = new Vector3(transform.forward.x, 0f, transform.forward.z).normalized;
                Vector3 right = new Vector3(transform.right.x, 0f, transform.right.z).normalized;
                Vector3 move = (right * h + forward * v) * panSpeed * Time.deltaTime;
                _targetPosition += move;

                _targetPosition.x = Mathf.Clamp(_targetPosition.x, xBounds.x, xBounds.y);
                _targetPosition.z = Mathf.Clamp(_targetPosition.z, zBounds.x, zBounds.y);
            }
        }

        private void HandleZoom()
        {
            float scroll = Input.GetAxis("Mouse ScrollWheel");
            if (Mathf.Abs(scroll) > 0.001f)
            {
                _currentZoom -= scroll * zoomSpeed;
                _currentZoom = Mathf.Clamp(_currentZoom, minZoomDist, maxZoomDist);
                _targetPosition.y = _currentZoom;
            }
        }

        private void HandleKeyboardShortcuts()
        {
            // Focus hotkeys: 1 for J1, 2 for J2, 3 for J3, F for Frame All
            if (Input.GetKeyDown(KeyCode.Alpha1) && targetJ1 != null)
            {
                FocusOn(targetJ1.position);
            }
            else if (Input.GetKeyDown(KeyCode.Alpha2) && targetJ2 != null)
            {
                FocusOn(targetJ2.position);
            }
            else if (Input.GetKeyDown(KeyCode.Alpha3) && targetJ3 != null)
            {
                FocusOn(targetJ3.position);
            }
            else if (Input.GetKeyDown(KeyCode.F))
            {
                ResetStrategicView();
            }
            else if (Input.GetKeyDown(KeyCode.E))
            {
                FocusAmbulance();
            }
        }

        public void FocusAmbulance()
        {
            if (NexusTwin.Vehicles.VehicleManager.Instance != null)
            {
                foreach (var veh in NexusTwin.Vehicles.VehicleManager.Instance.activeVehicles)
                {
                    if (veh != null && (veh.isEmergency || veh.vehicleType == Data.VehicleType.Ambulance))
                    {
                        FocusOn(veh.transform.position);
                        return;
                    }
                }
            }
        }

        public void FocusOn(Vector3 worldPos)
        {
            mode = CameraMode.Strategic;
            _targetPosition = new Vector3(worldPos.x, 35f, worldPos.z - 30f);
        }

        public void FocusIncident(Transform target)
        {
            incidentTarget = target;
            mode = CameraMode.IncidentFocus;
        }

        public void ResetStrategicView()
        {
            mode = CameraMode.Strategic;
            _targetPosition = new Vector3(0f, 50f, -45f);
        }

        public void FocusJunction(string junctionId)
        {
            if (junctionId == "J1" && targetJ1 != null) FocusOn(targetJ1.position);
            else if (junctionId == "J2" && targetJ2 != null) FocusOn(targetJ2.position);
            else if (junctionId == "J3" && targetJ3 != null) FocusOn(targetJ3.position);
        }

        private void HandleIncidentTriggered(string junctionId, string incidentType)
        {
            Debug.Log($"[StrategicCamera] Incident detected at {junctionId}, auto-focusing");
            if (junctionId == NexusIds.Junctions.J1 && targetJ1 != null) FocusIncident(targetJ1);
            else if (junctionId == NexusIds.Junctions.J2 && targetJ2 != null) FocusIncident(targetJ2);
            else if (junctionId == NexusIds.Junctions.J3 && targetJ3 != null) FocusIncident(targetJ3);
        }
    }
}

using System;

namespace NexusTwin.Core
{
    /// <summary>
    /// Lightweight publish/subscribe event bus for decoupling game systems.
    /// Gameplay scripts raise events here; UI scripts listen.
    /// No direct coupling between gameplay logic and UI internals.
    /// </summary>
    public static class EventBus
    {
        // --- Traffic Events ---
        public static event Action<string, float> OnCongestionAlert;          // junctionId, probability
        public static event Action<string, string> OnIncidentTriggered;       // junctionId, incidentType
        public static event Action<string> OnIncidentResolved;                // junctionId

        // --- AI / Decision Events ---
        public static event Action<CongestionAlertData> OnAIPrediction;
        public static event Action<StrategyOptionData[]> OnStrategiesReady;
        public static event Action<ScenarioResultData[]> OnSimulationComplete;
        public static event Action<ExplanationData> OnExplanationReady;
        public static event Action<DisagreementData> OnDisagreementTriggered;

        // --- Player Action Events ---
        public static event Action<StrategyOptionData> OnStrategySelected;
        public static event Action OnSimulateRequested;
        public static event Action OnApproved;
        public static event Action OnRejected;
        public static event Action OnMissionRestart;
        public static event Action OnPlayClicked;

        // --- Score & Mission Events ---
        public static event Action<ScoreBreakdownData> OnScoreUpdated;
        public static event Action<ScoreBreakdownData> OnScenarioComplete;
        public static event Action<MissionFailureData> OnMissionFailed;

        // --- Game State Events ---
        public static event Action<Data.GameState> OnGameStateChanged;

        // --- Raise Methods ---
        public static void RaiseCongestionAlert(string junctionId, float probability)
            => OnCongestionAlert?.Invoke(junctionId, probability);

        public static void RaiseIncidentTriggered(string junctionId, string incidentType)
            => OnIncidentTriggered?.Invoke(junctionId, incidentType);

        public static void RaiseIncidentResolved(string junctionId)
            => OnIncidentResolved?.Invoke(junctionId);

        public static void RaiseAIPrediction(CongestionAlertData alert)
            => OnAIPrediction?.Invoke(alert);

        public static void RaiseStrategiesReady(StrategyOptionData[] options)
            => OnStrategiesReady?.Invoke(options);

        public static void RaiseSimulationComplete(ScenarioResultData[] results)
            => OnSimulationComplete?.Invoke(results);

        public static void RaiseExplanationReady(ExplanationData explanation)
            => OnExplanationReady?.Invoke(explanation);

        public static void RaiseDisagreementTriggered(DisagreementData disagreement)
            => OnDisagreementTriggered?.Invoke(disagreement);

        public static void RaiseStrategySelected(StrategyOptionData option)
            => OnStrategySelected?.Invoke(option);

        public static void RaiseSimulateRequested()
            => OnSimulateRequested?.Invoke();

        public static void RaiseApproved()
            => OnApproved?.Invoke();

        public static void RaiseRejected()
            => OnRejected?.Invoke();

        public static void RaiseMissionRestart()
            => OnMissionRestart?.Invoke();

        public static void RaisePlayClicked()
            => OnPlayClicked?.Invoke();

        public static void RaiseScoreUpdated(ScoreBreakdownData score)
            => OnScoreUpdated?.Invoke(score);

        public static void RaiseScenarioComplete(ScoreBreakdownData score)
            => OnScenarioComplete?.Invoke(score);

        public static void RaiseMissionFailed(MissionFailureData failure)
            => OnMissionFailed?.Invoke(failure);

        public static void RaiseGameStateChanged(Data.GameState state)
            => OnGameStateChanged?.Invoke(state);
    }

    // --- Event Data Structs ---

    [Serializable]
    public struct DisagreementData
    {
        public string playerAction;
        public string aiRecommendation;
        public string tradeOffReason;
        public float networkDelayDeltaPct;
        public float emergencyDelayDeltaS;
    }

    [Serializable]
    public struct MissionFailureData
    {
        public string title;
        public string reason;
        public float finalQueue;
        public float ambulanceDelay;
    }

    [Serializable]
    public struct CongestionAlertData
    {
        public string junctionId;
        public float probability;
        public int forecastMinutes;
        public float confidence;
    }

    [Serializable]
    public struct StrategyOptionData
    {
        public Data.StrategyType type;
        public string label;
        public string strategyTypeString; // backend-compatible string from NexusIds
        public float extensionSeconds;    // for green_extend
        public float diversionPercent;    // for diversion
    }

    [Serializable]
    public struct ScenarioResultData
    {
        public Data.StrategyType type;
        public string label;
        public float delayDeltaPct;
        public float queueDeltaPct;
        public float emissionsDeltaPct;
        public float emergencyDelayS;
        public bool isBest;
    }

    [Serializable]
    public struct ExplanationData
    {
        public string action;
        public string reason;
        public string evidence;
        public float confidence;
    }

    [Serializable]
    public struct ScoreBreakdownData
    {
        public int trafficFlow;
        public int emergencySafety;
        public int queueControl;
        public int decisionQuality;
        public int Total => trafficFlow + emergencySafety + queueControl + decisionQuality;
    }
}

using UnityEngine;
using NexusTwin.Data;

namespace NexusTwin.Core
{
    /// <summary>
    /// GameManager — Singleton that persists across scenes.
    /// Manages session lifecycle and routes between game states.
    /// </summary>
    public class GameManager : MonoBehaviour
    {
        public static GameManager Instance { get; private set; }

        [Header("Session")]
        public string playerName = "Commander";
        public string currentMode = "free_play";
        public string difficulty = "normal";

        [Header("Runtime State")]
        public GameState currentState = GameState.MainMenu;
        public bool isBackendConnected = false;
        public bool useMockData = true; // Stage A: true. Stage B (step 17): false.
        public int currentMission = 1;

        private void Awake()
        {
            if (Instance != null && Instance != this)
            {
                Destroy(gameObject);
                return;
            }
            Instance = this;
            DontDestroyOnLoad(gameObject);
        }

        /// <summary>
        /// Transition to a new game state with validation.
        /// Invalid transitions are logged and rejected.
        /// </summary>
        public void SetState(GameState newState)
        {
            if (!IsValidTransition(currentState, newState))
            {
                Debug.LogWarning($"[GameManager] Invalid state transition: {currentState} -> {newState}");
                return;
            }

            Debug.Log($"[GameManager] State: {currentState} -> {newState}");
            currentState = newState;
            EventBus.RaiseGameStateChanged(newState);
        }

        /// <summary>
        /// State machine transition validation per GAME_STATE_MACHINE.md.
        /// </summary>
        private bool IsValidTransition(GameState from, GameState to)
        {
            if (from == to) return true;

            switch (from)
            {
                case GameState.MainMenu:   return to == GameState.Cinematic || to == GameState.Briefing || to == GameState.Idle;
                case GameState.Cinematic:  return to == GameState.Briefing || to == GameState.Idle || to == GameState.MainMenu;
                case GameState.Briefing:   return to == GameState.Idle || to == GameState.MainMenu;
                case GameState.Idle:       return to == GameState.Event || to == GameState.MainMenu || to == GameState.Briefing;
                case GameState.Event:      return to == GameState.Analysis || to == GameState.Failed;
                case GameState.Analysis:   return to == GameState.Decision || to == GameState.Failed;
                case GameState.Decision:   return to == GameState.Simulation || to == GameState.Approval || to == GameState.Failed;
                case GameState.Simulation: return to == GameState.Comparison || to == GameState.Failed;
                case GameState.Comparison: return to == GameState.Explanation || to == GameState.Approval || to == GameState.Failed;
                case GameState.Explanation:return to == GameState.Approval || to == GameState.Decision || to == GameState.Failed;
                case GameState.Approval:   return to == GameState.Apply || to == GameState.Decision || to == GameState.Failed; // reject loops back or fails
                case GameState.Apply:      return to == GameState.Result || to == GameState.Failed;
                case GameState.Result:     return to == GameState.Score || to == GameState.Failed;
                case GameState.Score:      return to == GameState.Idle || to == GameState.Briefing || to == GameState.MainMenu || to == GameState.NextEvent;
                case GameState.Failed:     return to == GameState.Idle || to == GameState.Briefing || to == GameState.MainMenu || to == GameState.Cinematic;
                case GameState.NextEvent:  return to == GameState.Event || to == GameState.Idle || to == GameState.MainMenu;
                default: return true;
            }
        }
    }
}

