using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using NexusTwin.Data;
using NexusTwin.Core;
using NexusTwin.Vehicles;

namespace NexusTwin.DigitalTwin
{
    /// <summary>
    /// DigitalTwinSimulationView — Visually Undeniable Digital Twin Simulation.
    /// Phase C implementation:
    /// When "SIMULATE FUTURES" is triggered, splits/sweeps the city visually into 4 predicted counterfactual futures:
    /// - Future A (Divert Traffic): Translucent blue/green ghost vehicles along bypass routes.
    /// - Future B (Extend Green): Amber/green ghost stream through main corridor.
    /// - Future C (Emergency Priority): Red/white ambulance ghost with translucent green path line.
    /// - Future D (Do Nothing): Pulsing crimson queue density rings & gridlocked ghost vehicles.
    /// Includes translucent route projections, predicted queue markers, and holographic scan effects.
    /// </summary>
    public class DigitalTwinSimulationView : MonoBehaviour
    {
        public static DigitalTwinSimulationView Instance { get; private set; }

        [Header("Simulation State")]
        public bool isSimulationMode = false;
        public int activeFutureIndex = 0; // 0=A, 1=B, 2=C, 3=D

        [Header("Holographic Color Palette")]
        public Color ghostCyan     = new Color(0.10f, 0.70f, 0.95f, 0.55f); // Future A: Divert
        public Color ghostAmber    = new Color(0.95f, 0.72f, 0.15f, 0.55f); // Future B: Extend Green
        public Color ghostRed      = new Color(0.95f, 0.20f, 0.15f, 0.65f); // Future D: Do Nothing
        public Color ghostEmergency= new Color(0.20f, 0.95f, 0.40f, 0.65f); // Future C: Emergency Priority

        private List<GameObject> _ghostObjects = new List<GameObject>();
        private List<GameObject> _routeLineObjects = new List<GameObject>();
        private List<GameObject> _queueZoneObjects = new List<GameObject>();
        private Coroutine _sweepRoutine;

        private void Awake()
        {
            if (Instance != null && Instance != this) { Destroy(gameObject); return; }
            Instance = this;
        }

        private void Start()
        {
            EventBus.OnGameStateChanged += HandleGameStateChanged;
            EventBus.OnSimulationComplete += HandleSimulationComplete;
        }

        private void OnDestroy()
        {
            EventBus.OnGameStateChanged -= HandleGameStateChanged;
            EventBus.OnSimulationComplete -= HandleSimulationComplete;
        }

        private void HandleGameStateChanged(GameState state)
        {
            if (state == GameState.Simulation || state == GameState.Comparison)
            {
                EnterSimulationMode();
            }
            else if (state == GameState.Apply || state == GameState.Idle || state == GameState.Result || state == GameState.Score)
            {
                ExitSimulationMode();
            }
        }

        public void EnterSimulationMode()
        {
            if (isSimulationMode) return;
            isSimulationMode = true;
            Debug.Log("[DigitalTwinSimulationView] Entering Multi-Future Digital Twin Holographic Simulation");

            if (_sweepRoutine != null) StopCoroutine(_sweepRoutine);
            _sweepRoutine = StartCoroutine(RunMultiFutureSweepRoutine());
        }

        public void ExitSimulationMode()
        {
            if (!isSimulationMode) return;
            isSimulationMode = false;
            if (_sweepRoutine != null) StopCoroutine(_sweepRoutine);
            ClearAllSimulationVisuals();
            Debug.Log("[DigitalTwinSimulationView] Exiting Holographic Twin Simulation Mode -> Restoring Real World");
        }

        private void HandleSimulationComplete(ScenarioResultData[] results)
        {
            // Keep rendering active ghost state
            if (!isSimulationMode) EnterSimulationMode();
        }

        /// <summary>
        /// Sweeps sequentially through Future A, B, C, and D visual states to show
        /// the human operator all 4 counterfactual futures projected onto the physical city plane.
        /// </summary>
        private IEnumerator RunMultiFutureSweepRoutine()
        {
            // Sweep Future A -> B -> C -> D -> Show All Combined
            for (int future = 0; future < 4; future++)
            {
                activeFutureIndex = future;
                RenderFutureState(future);
                yield return new WaitForSeconds(0.75f);
            }

            // Finally, render composite state displaying all 4 futures side-by-side with translucent routes
            RenderAllFuturesComposite();
        }

        private void RenderFutureState(int futureIndex)
        {
            ClearAllSimulationVisuals();

            switch (futureIndex)
            {
                case 0: // Future A: Divert Traffic (Cyan/Green Bypass Stream)
                    SpawnGhostRouteLine(new Vector3(2.5f, 0.15f, 80f), new Vector3(2.5f, 0.15f, 60f), ghostCyan);
                    SpawnGhostRouteLine(new Vector3(2.5f, 0.15f, 60f), new Vector3(45f, 0.15f, 60f), ghostCyan);
                    SpawnGhostRouteLine(new Vector3(2.5f, 0.15f, 60f), new Vector3(-45f, 0.15f, 60f), ghostCyan);

                    for (int i = 0; i < 8; i++)
                    {
                        float x = (i % 2 == 0) ? (15f + i * 4f) : (-15f - i * 4f);
                        SpawnGhostVehicle(new Vector3(x, 0.6f, 60f), Quaternion.Euler(0f, 90f, 0f), ghostCyan, "Ghost_Divert_" + i);
                    }
                    SpawnQueueZone(new Vector3(0f, 0.05f, 0f), new Vector3(8f, 0.1f, 8f), new Color(0.2f, 0.8f, 0.3f, 0.25f));
                    break;

                case 1: // Future B: Extend Green (Amber Main Corridor Stream)
                    SpawnGhostRouteLine(new Vector3(2.5f, 0.15f, 80f), new Vector3(2.5f, 0.15f, -80f), ghostAmber);
                    for (int i = 0; i < 6; i++)
                    {
                        SpawnGhostVehicle(new Vector3(2.5f, 0.6f, 50f - i * 14f), Quaternion.Euler(0f, 180f, 0f), ghostAmber, "Ghost_GreenExtend_" + i);
                    }
                    // Side-street queue buildup
                    SpawnQueueZone(new Vector3(-25f, 0.05f, 0f), new Vector3(18f, 0.1f, 6f), new Color(0.95f, 0.70f, 0.10f, 0.35f));
                    break;

                case 2: // Future C: Emergency Priority (Bright Green EMS Wave + Red Clearance)
                    SpawnGhostRouteLine(new Vector3(2.5f, 0.20f, 85f), new Vector3(2.5f, 0.20f, -85f), ghostEmergency, width: 2.2f);
                    // Ambulance ghost
                    SpawnGhostVehicle(new Vector3(2.5f, 0.7f, 30f), Quaternion.Euler(0f, 180f, 0f), ghostEmergency, "Ghost_Ambulance_EMS", scale: new Vector3(2.1f, 2.1f, 5.2f));

                    // Stopped side traffic ghosts (Red)
                    SpawnGhostVehicle(new Vector3(-12f, 0.6f, 2.5f), Quaternion.Euler(0f, 90f, 0f), ghostRed, "Ghost_Stopped_W");
                    SpawnGhostVehicle(new Vector3(12f, 0.6f, -2.5f), Quaternion.Euler(0f, 270f, 0f), ghostRed, "Ghost_Stopped_E");
                    break;

                case 3: // Future D: Do Nothing (Pulsing Crimson Gridlock)
                    for (int i = 0; i < 12; i++)
                    {
                        float z = 20f - (i * 4f);
                        float x = (i % 2 == 0) ? 2.5f : 4.5f;
                        SpawnGhostVehicle(new Vector3(x, 0.6f, z), Quaternion.Euler(0f, 180f, 0f), ghostRed, "Ghost_Gridlock_" + i);
                    }
                    // Large crimson bottleneck queue zone at J2
                    SpawnQueueZone(new Vector3(0f, 0.05f, 0f), new Vector3(32f, 0.1f, 32f), new Color(0.85f, 0.10f, 0.10f, 0.45f));
                    break;
            }
        }

        private void RenderAllFuturesComposite()
        {
            ClearAllSimulationVisuals();

            // 1. Bypass diversion stream (Future A)
            SpawnGhostRouteLine(new Vector3(2.5f, 0.15f, 60f), new Vector3(45f, 0.15f, 60f), ghostCyan);
            for (int i = 0; i < 4; i++)
                SpawnGhostVehicle(new Vector3(18f + i * 6f, 0.6f, 60f), Quaternion.Euler(0f, 90f, 0f), ghostCyan, "Ghost_A_" + i);

            // 2. Emergency Priority route (Future C)
            SpawnGhostRouteLine(new Vector3(2.5f, 0.20f, 85f), new Vector3(2.5f, 0.20f, -85f), ghostEmergency, width: 2.4f);
            SpawnGhostVehicle(new Vector3(2.5f, 0.7f, 35f), Quaternion.Euler(0f, 180f, 0f), ghostEmergency, "Ghost_Ambulance", scale: new Vector3(2.1f, 2.1f, 5.2f));

            // 3. Gridlock Queue Zone at J2 (Future D baseline)
            SpawnQueueZone(new Vector3(0f, 0.05f, 0f), new Vector3(26f, 0.08f, 26f), new Color(0.85f, 0.15f, 0.15f, 0.30f));
        }

        // ──────── Visual Spawners ────────
        private GameObject SpawnGhostVehicle(Vector3 pos, Quaternion rot, Color col, string name, Vector3? scale = null)
        {
            GameObject ghost = GameObject.CreatePrimitive(PrimitiveType.Cube);
            ghost.name = name;
            ghost.transform.SetParent(transform, false);
            ghost.transform.position = pos;
            ghost.transform.rotation = rot;
            ghost.transform.localScale = scale ?? new Vector3(1.8f, 1.2f, 3.8f);

            Renderer r = ghost.GetComponent<Renderer>();
            if (r != null)
            {
                Material mat = new Material(Shader.Find("Standard") ?? Shader.Find("Legacy Shaders/Diffuse"));
                mat.color = col;
                if (mat.HasProperty("_EmissionColor"))
                {
                    mat.EnableKeyword("_EMISSION");
                    mat.SetColor("_EmissionColor", col * 1.5f);
                }
                r.material = mat;
            }
            Destroy(ghost.GetComponent<Collider>());
            _ghostObjects.Add(ghost);
            return ghost;
        }

        private void SpawnGhostRouteLine(Vector3 start, Vector3 end, Color col, float width = 1.6f)
        {
            GameObject lineObj = new GameObject("GhostRouteLine");
            lineObj.transform.SetParent(transform, false);

            Vector3 mid = (start + end) * 0.5f;
            Vector3 diff = end - start;
            float len = diff.magnitude;

            lineObj.transform.position = mid;
            lineObj.transform.rotation = Quaternion.LookRotation(diff);
            lineObj.transform.localScale = new Vector3(width, 0.06f, len);

            GameObject cube = GameObject.CreatePrimitive(PrimitiveType.Cube);
            cube.transform.SetParent(lineObj.transform, false);
            cube.transform.localPosition = Vector3.zero;
            cube.transform.localScale = Vector3.one;

            Renderer r = cube.GetComponent<Renderer>();
            if (r != null)
            {
                Material mat = new Material(Shader.Find("Standard") ?? Shader.Find("Legacy Shaders/Diffuse"));
                mat.color = col;
                if (mat.HasProperty("_EmissionColor"))
                {
                    mat.EnableKeyword("_EMISSION");
                    mat.SetColor("_EmissionColor", col * 2.0f);
                }
                r.material = mat;
            }
            Destroy(cube.GetComponent<Collider>());
            _routeLineObjects.Add(lineObj);
        }

        private void SpawnQueueZone(Vector3 pos, Vector3 size, Color col)
        {
            GameObject qObj = GameObject.CreatePrimitive(PrimitiveType.Cube);
            qObj.name = "PredictedQueueZone";
            qObj.transform.SetParent(transform, false);
            qObj.transform.position = pos;
            qObj.transform.localScale = size;

            Renderer r = qObj.GetComponent<Renderer>();
            if (r != null)
            {
                Material mat = new Material(Shader.Find("Standard") ?? Shader.Find("Legacy Shaders/Diffuse"));
                mat.color = col;
                if (mat.HasProperty("_EmissionColor"))
                {
                    mat.EnableKeyword("_EMISSION");
                    mat.SetColor("_EmissionColor", col * 1.8f);
                }
                r.material = mat;
            }
            Destroy(qObj.GetComponent<Collider>());
            _queueZoneObjects.Add(qObj);
        }

        private void ClearAllSimulationVisuals()
        {
            foreach (var g in _ghostObjects) if (g != null) Destroy(g);
            foreach (var r in _routeLineObjects) if (r != null) Destroy(r);
            foreach (var q in _queueZoneObjects) if (q != null) Destroy(q);
            _ghostObjects.Clear();
            _routeLineObjects.Clear();
            _queueZoneObjects.Clear();
        }
    }
}

using System.Collections.Generic;
using UnityEngine;
using NexusTwin.Data;
using NexusTwin.Core;
using NexusTwin.Traffic;

namespace NexusTwin.Gameplay
{
    /// <summary>
    /// IncidentManager — Tracks and visualizes active traffic incidents across the network.
    /// Spawns physical accident scenes with disabled vehicles, flashing hazard lights,
    /// and reflective safety cones to force realistic queue propagation.
    /// </summary>
    public class IncidentManager : MonoBehaviour
    {
        public static IncidentManager Instance { get; private set; }

        private Dictionary<string, GameObject> _activeHazardMarkers = new Dictionary<string, GameObject>();

        private void Awake()
        {
            if (Instance != null && Instance != this)
            {
                Destroy(gameObject);
                return;
            }
            Instance = this;
        }

        private void Start()
        {
            EventBus.OnIncidentTriggered += HandleIncidentTriggered;
            EventBus.OnIncidentResolved += HandleIncidentResolved;
        }

        private void OnDestroy()
        {
            EventBus.OnIncidentTriggered -= HandleIncidentTriggered;
            EventBus.OnIncidentResolved -= HandleIncidentResolved;
        }

        public void TriggerIncident(string junctionId, IncidentType type, Vector3 location)
        {
            Debug.Log($"[IncidentManager] Triggered {type} at {junctionId} (pos: {location})");

            if (!_activeHazardMarkers.ContainsKey(junctionId))
            {
                GameObject marker = CreateAccidentScene(location, type);
                _activeHazardMarkers[junctionId] = marker;
            }

            Junction j = FindJunction(junctionId);
            if (j != null)
            {
                j.TriggerIncident(type);
            }

            EventBus.RaiseIncidentTriggered(junctionId, type.ToString().ToLower());
        }

        public void ResolveIncident(string junctionId)
        {
            Debug.Log($"[IncidentManager] Resolved incident at {junctionId}");

            if (_activeHazardMarkers.TryGetValue(junctionId, out GameObject marker))
            {
                Destroy(marker);
                _activeHazardMarkers.Remove(junctionId);
            }

            Junction j = FindJunction(junctionId);
            if (j != null)
            {
                j.ResolveIncident();
            }

            EventBus.RaiseIncidentResolved(junctionId);
        }

        private GameObject CreateAccidentScene(Vector3 pos, IncidentType type)
        {
            GameObject sceneRoot = new GameObject($"AccidentScene_{type}");
            sceneRoot.transform.position = pos;

            // 1. Damaged Vehicle (Tilted dark sedan)
            GameObject car = GameObject.CreatePrimitive(PrimitiveType.Cube);
            car.name = "DamagedVehicle";
            car.tag = "Vehicle"; // Raycast obstacle for active vehicles
            car.transform.SetParent(sceneRoot.transform, false);
            car.transform.localPosition = new Vector3(0f, 0.6f, 0f);
            car.transform.localRotation = Quaternion.Euler(0f, 35f, 8f);
            car.transform.localScale = new Vector3(1.8f, 1.2f, 3.8f);
            car.GetComponent<Renderer>().material.color = new Color(0.2f, 0.22f, 0.28f);

            // Car roof / cabin
            GameObject cabin = GameObject.CreatePrimitive(PrimitiveType.Cube);
            cabin.name = "Cabin";
            cabin.transform.SetParent(car.transform, false);
            cabin.transform.localPosition = new Vector3(0f, 0.5f, -0.1f);
            cabin.transform.localScale = new Vector3(0.9f, 0.65f, 0.55f);
            cabin.GetComponent<Renderer>().material.color = new Color(0.12f, 0.14f, 0.18f);

            // 2. Warning Cones with reflective stripes
            Vector3[] coneOffsets = new Vector3[]
            {
                new Vector3(-1.2f, 0f, 3.0f),
                new Vector3(1.2f, 0f, 3.2f),
                new Vector3(-1.4f, 0f, -3.2f),
                new Vector3(1.4f, 0f, -3.0f)
            };

            foreach (var offset in coneOffsets)
            {
                GameObject cone = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
                cone.name = "SafetyCone";
                cone.tag = "Vehicle";
                cone.transform.SetParent(sceneRoot.transform, false);
                cone.transform.localPosition = new Vector3(offset.x, 0.35f, offset.z);
                cone.transform.localScale = new Vector3(0.45f, 0.35f, 0.45f);
                cone.GetComponent<Renderer>().material.color = new Color(1.0f, 0.45f, 0.05f); // Fluorescent Orange

                // Reflective white band
                GameObject band = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
                band.name = "ReflectiveBand";
                band.transform.SetParent(cone.transform, false);
                band.transform.localPosition = new Vector3(0f, 0.2f, 0f);
                band.transform.localScale = new Vector3(1.02f, 0.3f, 1.02f);
                band.GetComponent<Renderer>().material.color = Color.white;
            }

            // 3. Pulsing Amber Hazard Light Beacon
            GameObject lightObj = new GameObject("HazardBeacon");
            lightObj.transform.SetParent(sceneRoot.transform, false);
            lightObj.transform.localPosition = new Vector3(0f, 1.8f, 0f);
            Light l = lightObj.AddComponent<Light>();
            l.color = new Color(1.0f, 0.6f, 0.1f);
            l.range = 14f;
            l.intensity = 3.0f;

            return sceneRoot;
        }

        private Junction FindJunction(string id)
        {
            Junction[] junctions = FindObjectsByType<Junction>(FindObjectsSortMode.None);
            foreach (Junction j in junctions)
            {
                if (j.junctionId == id) return j;
            }
            return null;
        }

        private void HandleIncidentTriggered(string junctionId, string incidentType) { }
        private void HandleIncidentResolved(string junctionId) { }
    }
}

using UnityEngine;
using NexusTwin.Data;

namespace NexusTwin.Gameplay
{
    /// <summary>
    /// IncidentTrigger — Attached to locations or timers to trigger incidents during scenarios.
    /// Implements Phase F requirements.
    /// </summary>
    public class IncidentTrigger : MonoBehaviour
    {
        public string junctionId = NexusIds.Junctions.J2;
        public IncidentType incidentType = IncidentType.Accident;
        public float triggerTimeSeconds = 20.0f;
        public bool hasTriggered = false;

        private float _elapsed = 0f;

        private void Update()
        {
            if (hasTriggered) return;

            _elapsed += Time.deltaTime;
            if (_elapsed >= triggerTimeSeconds)
            {
                Trigger();
            }
        }

        public void Trigger()
        {
            if (hasTriggered) return;
            hasTriggered = true;

            IncidentManager.Instance?.TriggerIncident(junctionId, incidentType, transform.position);
            Debug.Log($"[IncidentTrigger] Fired {incidentType} at {junctionId} (T={_elapsed:F1}s)");
        }
    }
}

using System.Collections;
using UnityEngine;
using UnityEngine.UI;
using NexusTwin.Core;
using NexusTwin.Audio;
using NexusTwin.Data;
using NexusTwin.Camera;

namespace NexusTwin.Gameplay
{
    public class IntroCinematicController : MonoBehaviour
    {
        public static IntroCinematicController Instance { get; private set; }

        public GameObject cinematicUIRoot;
        public CanvasGroup fadeCanvasGroup;
        public Text subtitleText;
        public Text hackerTerminalText;
        public GameObject hackerTerminalBox;
        public Button skipButton;

        private Coroutine _cinematicRoutine;
        private bool _isSkipped = false;

        private void Awake()
        {
            if (Instance != null && Instance != this)
            {
                Destroy(gameObject);
                return;
            }
            Instance = this;
        }

        private void Start()
        {
            if (skipButton != null)
                skipButton.onClick.AddListener(SkipCinematic);

            EventBus.OnGameStateChanged += HandleGameStateChanged;
        }

        private void OnDestroy()
        {
            EventBus.OnGameStateChanged -= HandleGameStateChanged;
        }

        private void Update()
        {
            if (GameManager.Instance != null && GameManager.Instance.currentState == GameState.Cinematic)
            {
                if (Input.GetKeyDown(KeyCode.Space) || Input.GetKeyDown(KeyCode.Escape))
                {
                    SkipCinematic();
                }
            }
        }

        private void HandleGameStateChanged(GameState state)
        {
            if (state == GameState.Cinematic)
            {
                StartCinematic();
            }
            else
            {
                if (cinematicUIRoot != null) cinematicUIRoot.SetActive(false);
            }
        }

        public void StartCinematic()
        {
            if (cinematicUIRoot != null) cinematicUIRoot.SetActive(true);
            _isSkipped = false;
            if (_cinematicRoutine != null) StopCoroutine(_cinematicRoutine);
            _cinematicRoutine = StartCoroutine(CinematicSequence());
        }

        public void SkipCinematic()
        {
            if (_isSkipped) return;
            _isSkipped = true;
            SoundManager.Instance?.PlayClick();
            if (_cinematicRoutine != null) StopCoroutine(_cinematicRoutine);
            if (cinematicUIRoot != null) cinematicUIRoot.SetActive(false);
            GameManager.Instance?.SetState(GameState.Briefing);
        }

        private IEnumerator CinematicSequence()
        {
            // 1. Initial Black Screen + Ambience
            if (fadeCanvasGroup != null) fadeCanvasGroup.alpha = 1f;
            if (hackerTerminalBox != null) hackerTerminalBox.SetActive(false);
            SetSubtitle("EXT. METROPOLITAN CORRIDOR — 02:41 AM\n[POLICE RADIO: 'All units, 10-33 disruption reported near Sector J2...']");
            yield return new WaitForSeconds(3.5f);
            if (_isSkipped) yield break;

            // 2. Fade into City View
            float fadeTime = 2f;
            for (float t = 0; t < fadeTime; t += Time.deltaTime)
            {
                if (fadeCanvasGroup != null) fadeCanvasGroup.alpha = Mathf.Lerp(1f, 0f, t / fadeTime);
                yield return null;
            }
            if (fadeCanvasGroup != null) fadeCanvasGroup.alpha = 0f;

            // 3. The Heist / Suspicious Convoy
            SetSubtitle("A high-value heist convoy maneuvers into the central corridor.");
            StrategicCameraController.Instance?.FocusJunction("J1");
            yield return new WaitForSeconds(4f);
            if (_isSkipped) yield break;

            // 4. Hacker Intrusion Terminal Opens
            if (hackerTerminalBox != null) hackerTerminalBox.SetActive(true);
            SoundManager.Instance?.PlayAlert();
            if (hackerTerminalText != null)
            {
                hackerTerminalText.text = "> INTRUSION DETECTED: UNKNOWN ACTOR\n> ACCESSING TRAFFIC CONTROLLER J2...\n> OVERRIDE SIGNAL: FORCE GREEN NORTHBOUND\n> TRAFFIC DENSITY SPIKING: CRITICAL";
            }
            SetSubtitle("THE AI HACKER: Traffic signals hijacked at J2. Deliberate bottleneck forming.");
            StrategicCameraController.Instance?.FocusJunction("J2");
            yield return new WaitForSeconds(5.5f);
            if (_isSkipped) yield break;

            // 5. Emergency Siren Sounds
            if (hackerTerminalBox != null) hackerTerminalBox.SetActive(false);
            SoundManager.Instance?.StartSiren();
            SetSubtitle("🚨 EMERGENCY RESPONSE: AMBULANCE_01 EN ROUTE TO TRAUMA CENTER.\nCorridor blockage imminent!");
            StrategicCameraController.Instance?.FocusJunction("J3");
            yield return new WaitForSeconds(4.5f);
            SoundManager.Instance?.StopSiren();
            if (_isSkipped) yield break;

            // 6. Transition to Player Control Room
            SetSubtitle("NEXUS-TWIN OPERATOR ONLINE.\nYou are in command of the city digital twin network.");
            yield return new WaitForSeconds(3f);
            if (_isSkipped) yield break;

            if (cinematicUIRoot != null) cinematicUIRoot.SetActive(false);
            GameManager.Instance?.SetState(GameState.Briefing);
        }

        private void SetSubtitle(string text)
        {
            if (subtitleText != null)
            {
                subtitleText.text = text;
            }
        }
    }
}

using UnityEngine;
using NexusTwin.Data;
using NexusTwin.Traffic;
using NexusTwin.Vehicles;
using NexusTwin.Core;
using NexusTwin.Audio;

namespace NexusTwin.Gameplay
{
    /// <summary>
    /// SandboxModeController — Free Play / Interactive Sandbox mode controller.
    /// Allows the human operator to manually click traffic lights to toggle phases,
    /// trigger custom incidents with right-click, dispatch emergency vehicles, and test AI.
    /// </summary>
    public class SandboxModeController : MonoBehaviour
    {
        public static SandboxModeController Instance { get; private set; }

        [Header("Mode Configuration")]
        public bool isSandboxActive = true;
        public LayerMask clickableLayer;

        private void Awake()
        {
            if (Instance != null && Instance != this)
            {
                Destroy(gameObject);
                return;
            }
            Instance = this;
        }

        private void Update()
        {
            if (!isSandboxActive) return;

            HandleMouseInteraction();
            HandleHotkeyTriggers();
        }

        private void HandleMouseInteraction()
        {
            // Left click to toggle traffic signal phase
            if (Input.GetMouseButtonDown(0))
            {
                Ray ray = UnityEngine.Camera.main.ScreenPointToRay(Input.mousePosition);
                if (Physics.Raycast(ray, out RaycastHit hit, 200f))
                {
                    TrafficLightController tlc = hit.collider.GetComponentInParent<TrafficLightController>();
                    if (tlc != null)
                    {
                        ToggleSignal(tlc);
                        SoundManager.Instance?.PlayClick();
                    }
                }
            }

            // Right click to spawn incident at click location
            if (Input.GetMouseButtonDown(1) && Input.GetKey(KeyCode.LeftShift))
            {
                Ray ray = UnityEngine.Camera.main.ScreenPointToRay(Input.mousePosition);
                if (Physics.Raycast(ray, out RaycastHit hit, 200f))
                {
                    SpawnCustomIncident(hit.point);
                }
            }
        }

        private void HandleHotkeyTriggers()
        {
            // Hotkey 'E': Dispatch Emergency Ambulance
            if (Input.GetKeyDown(KeyCode.E))
            {
                VehicleManager.Instance?.SpawnEmergencyAmbulance();
                SoundManager.Instance?.StartSiren();
                Debug.Log("[SandboxMode] Dispatched Emergency Ambulance via Hotkey [E]");
            }

            // Hotkey 'I': Spawn Accident at J2
            if (Input.GetKeyDown(KeyCode.I))
            {
                SpawnCustomIncident(new Vector3(2.5f, 0f, 0f));
            }

            // Hotkey 'C': Force AI Predictor analysis
            if (Input.GetKeyDown(KeyCode.C))
            {
                CongestionAlertData alert = new CongestionAlertData
                {
                    junctionId = NexusIds.Junctions.J2,
                    probability = 0.91f,
                    forecastMinutes = 5
                };
                EventBus.RaiseAIPrediction(alert);
                SoundManager.Instance?.PlayAlert();
                Debug.Log("[SandboxMode] Triggered AI Congestion Forecast via Hotkey [C]");
            }
        }

        private void ToggleSignal(TrafficLightController tlc)
        {
            if (tlc.currentSignal == TrafficLightController.SignalColor.Green)
            {
                tlc.SetSignalColor(TrafficLightController.SignalColor.Red);
            }
            else
            {
                tlc.SetSignalColor(TrafficLightController.SignalColor.Green);
            }
            Debug.Log($"[SandboxMode] Manually toggled signal {tlc.junctionId} Approach {tlc.approachIndex} -> {tlc.currentSignal}");
        }

        private void SpawnCustomIncident(Vector3 location)
        {
            IncidentManager.Instance?.TriggerIncident(NexusIds.Junctions.J2, IncidentType.Accident, location);
            SoundManager.Instance?.PlayAlert();
            Debug.Log($"[SandboxMode] Custom Incident spawned at {location}");
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using NexusTwin.Data;
using NexusTwin.Core;
using NexusTwin.Vehicles;
using NexusTwin.Traffic;
using NexusTwin.Scoring;
using NexusTwin.Networking;
using NexusTwin.UI;

namespace NexusTwin.Gameplay
{
    /// <summary>
    /// ScenarioDirector — Directs the primary mission:
    /// Accident at J2 + Approaching Ambulance + AI Prediction + Digital Twin Simulation + Responsible AI Decisions.
    /// Supports Main Menu, Narrative Cinematic, Mission Briefing, Failure, and Score Debriefing.
    /// </summary>
    public class ScenarioDirector : MonoBehaviour
    {
        public static ScenarioDirector Instance { get; private set; }

        [Header("Scenario Settings")]
        public float scenarioTimer = 0f;
        public StrategyType aiRecommendedType = StrategyType.Diversion;

        [Header("State Tracking")]
        public bool incidentOccurred = false;
        public bool predictionFired = false;
        public bool recommendationFired = false;
        public bool simulationRequested = false;
        public bool decisionMade = false;
        public bool ambulanceDispatched = false;
        public bool scenarioCompleted = false;

        [Header("Player Choices")]
        public StrategyOptionData selectedStrategy;
        public bool approved = false;

        private VehicleAgent _ambulanceAgent;
        private Coroutine _scenarioRoutine;
        private IGameDataProvider _dataProvider;

        private void Awake()
        {
            if (Instance != null && Instance != this)
            {
                Destroy(gameObject);
                return;
            }
            Instance = this;
            if (GameManager.Instance != null && !GameManager.Instance.useMockData)
            {
                _dataProvider = new LiveGameDataProvider();
            }
            else
            {
                _dataProvider = new MockGameDataProvider();
            }
        }

        private void Start()
        {
            EventBus.OnStrategySelected += HandleStrategySelected;
            EventBus.OnSimulateRequested += HandleSimulateRequested;
            EventBus.OnApproved += HandleApproved;
            EventBus.OnRejected += HandleRejected;
            EventBus.OnMissionRestart += HandleMissionRestart;
            EventBus.OnGameStateChanged += HandleGameStateChanged;

            // Initialize in MainMenu
            if (GameManager.Instance != null)
            {
                GameManager.Instance.SetState(GameState.MainMenu);
            }
        }

        private void OnDestroy()
        {
            EventBus.OnStrategySelected -= HandleStrategySelected;
            EventBus.OnSimulateRequested -= HandleSimulateRequested;
            EventBus.OnApproved -= HandleApproved;
            EventBus.OnRejected -= HandleRejected;
            EventBus.OnMissionRestart -= HandleMissionRestart;
            EventBus.OnGameStateChanged -= HandleGameStateChanged;
        }

        private void Update()
        {
            if (!scenarioCompleted && GameManager.Instance != null && GameManager.Instance.currentState >= GameState.Idle)
            {
                scenarioTimer += Time.deltaTime;
            }
        }

        private void HandleGameStateChanged(GameState state)
        {
            if (state == GameState.Idle && _scenarioRoutine == null)
            {
                _scenarioRoutine = StartCoroutine(ScenarioSequenceRoutine());
            }
        }

        private void HandleMissionRestart()
        {
            if (_scenarioRoutine != null) StopCoroutine(_scenarioRoutine);
            _scenarioRoutine = null;

            scenarioTimer = 0f;
            incidentOccurred = false;
            predictionFired = false;
            recommendationFired = false;
            simulationRequested = false;
            decisionMade = false;
            ambulanceDispatched = false;
            scenarioCompleted = false;
            approved = false;

            IncidentManager.Instance?.ResolveIncident(NexusIds.Junctions.J2);
            IncidentManager.Instance?.ResolveIncident(NexusIds.Junctions.J3);
            GameManager.Instance?.SetState(GameState.Briefing);
        }

        private IEnumerator ScenarioSequenceRoutine()
        {
            int mission = (GameManager.Instance != null) ? GameManager.Instance.currentMission : 1;

            if (mission == 2)
            {
                Debug.Log("[ScenarioDirector] 00:00 - Mission 02 Active: Monitoring Escape Corridor J1-J2-J3");
                yield return new WaitForSeconds(4f);

                // Stage 2: First Alert (J2 Bottleneck)
                GameManager.Instance?.SetState(GameState.Event);
                incidentOccurred = true;
                IncidentManager.Instance?.TriggerIncident(NexusIds.Junctions.J2, IncidentType.Accident, new Vector3(2.5f, 0f, 0f));
                Debug.Log("[ScenarioDirector] 00:04 - Incident 1 triggered at J2");
                yield return new WaitForSeconds(4f);

                // Stage 3: Complication (J3 lane disruption)
                IncidentManager.Instance?.TriggerIncident(NexusIds.Junctions.J3, IncidentType.Closure, new Vector3(-2.5f, 0f, -60f));
                Debug.Log("[ScenarioDirector] 00:08 - Incident 2 triggered at J3 (lane closed)");
                yield return new WaitForSeconds(4f);

                // Stage 4: AI Alert with Uncertainty
                GameManager.Instance?.SetState(GameState.Analysis);
                predictionFired = true;
                _dataProvider.FetchAIPrediction(NexusIds.Junctions.J2, (alert) =>
                {
                    EventBus.RaiseAIPrediction(alert);
                });
                Debug.Log("[ScenarioDirector] 00:12 - AI predicts high congestion risk");
                yield return new WaitForSeconds(4f);

                // Stage 5: AI Recommendation & Decision
                GameManager.Instance?.SetState(GameState.Decision);
                recommendationFired = true;
                _dataProvider.FetchStrategies(NexusIds.Junctions.J2, (options) =>
                {
                    EventBus.RaiseStrategiesReady(options);
                    selectedStrategy = options[0]; // Coordinated Corridor is the AI Recommendation
                });
                yield return new WaitForSeconds(5f);

                // Stage 6: Digital Twin Simulation
                GameManager.Instance?.SetState(GameState.Simulation);
                Debug.Log("[ScenarioDirector] Digital Twin evaluating multi-junction futures...");
                yield return new WaitForSeconds(3f);

                GameManager.Instance?.SetState(GameState.Comparison);
                _dataProvider.SimulateFutures(NexusIds.Junctions.J2, selectedStrategy.type, (results) =>
                {
                    EventBus.RaiseSimulationComplete(results);
                });
                yield return new WaitForSeconds(3f);

                // Explanation
                GameManager.Instance?.SetState(GameState.Explanation);
                _dataProvider.FetchExplanation(selectedStrategy.type, (explanation) =>
                {
                    EventBus.RaiseExplanationReady(explanation);
                });
                yield return new WaitForSeconds(3f);

                // Stage 7: Decision Conflict / Approval
                GameManager.Instance?.SetState(GameState.Approval);
                Debug.Log("[ScenarioDirector] Awaiting operator priority decision...");

                float waitApprove = 0f;
                while (!decisionMade && waitApprove < 12f)
                {
                    waitApprove += Time.deltaTime;
                    yield return null;
                }

                if (!decisionMade)
                {
                    EventBus.RaiseApproved();
                }

                // Stage 8: Execution & Consequences
                if (selectedStrategy.type == StrategyType.DoNothing && approved)
                {
                    yield return new WaitForSeconds(4f);
                    GameManager.Instance?.SetState(GameState.Failed);
                    EventBus.RaiseMissionFailed(new MissionFailureData
                    {
                        title = "Escape Corridor Collapse",
                        reason = "No Action resulted in compounding bottlenecks at J2 and J3. Emergency transit gridlocked.",
                        finalQueue = 78f,
                        ambulanceDelay = 32.5f
                    });
                    yield break;
                }

                // Points popup for human operator decision
                if (selectedStrategy.type == StrategyType.Diversion)
                {
                    ScorePopupFX.ShowPopup("+250 PTS — OPTIMAL AI ALIGNMENT!", new Vector2(0, 100), new Color(0.22f, 0.906f, 0.372f));
                }
                else if (selectedStrategy.type == StrategyType.EmergencyPriority)
                {
                    ScorePopupFX.ShowPopup("+180 PTS — EMERGENCY ROUTE SECURED!", new Vector2(0, 100), new Color(0.10f, 0.53f, 0.82f));
                }
                else
                {
                    ScorePopupFX.ShowPopup("+100 PTS — INTERVENTION APPLIED", new Vector2(0, 100), new Color(0.95f, 0.72f, 0.15f));
                }

                GameManager.Instance?.SetState(GameState.Apply);
                Debug.Log($"[ScenarioDirector] Applying strategy override: {selectedStrategy.label}");

                TrafficLightController[] allLights = FindObjectsByType<TrafficLightController>(FindObjectsSortMode.None);
                foreach (var light in allLights)
                {
                    light.ApplyStrategyOverride(selectedStrategy.strategyTypeString, 45f);
                }
                yield return new WaitForSeconds(2f);

                // Dispatch Ambulance
                ambulanceDispatched = true;
                _ambulanceAgent = VehicleManager.Instance?.SpawnEmergencyAmbulance();
                Debug.Log("[ScenarioDirector] Ambulance entering escape corridor");
                yield return new WaitForSeconds(9f);

                // Stage 9: Resolve & Result
                GameManager.Instance?.SetState(GameState.Result);
                IncidentManager.Instance?.ResolveIncident(NexusIds.Junctions.J2);
                IncidentManager.Instance?.ResolveIncident(NexusIds.Junctions.J3);
                yield return new WaitForSeconds(4f);

                // Stage 10: Debrief
                GameManager.Instance?.SetState(GameState.Score);
                scenarioCompleted = true;

                ScoreBreakdownData scoreData = new ScoreBreakdownData();
                if (ScoreController.Instance != null)
                {
                    scoreData = new ScoreBreakdownData
                    {
                        trafficFlow = ScoreController.Instance.trafficFlowScore,
                        emergencySafety = ScoreController.Instance.emergencySafetyScore,
                        queueControl = ScoreController.Instance.queueControlScore,
                        decisionQuality = ScoreController.Instance.decisionQualityScore
                    };
                }
                else
                {
                    scoreData = new ScoreBreakdownData { trafficFlow = 290, emergencySafety = 330, queueControl = 210, decisionQuality = 150 };
                }

                EventBus.RaiseScoreUpdated(scoreData);
                EventBus.RaiseScenarioComplete(scoreData);
                yield break;
            }

            // Fallback to Mission 01 sequence if not mission 2
            Debug.Log("[ScenarioDirector] 00:00 - Mission 01 Active: Monitoring Corridor J1-J2-J3");
            yield return new WaitForSeconds(6f);

            GameManager.Instance?.SetState(GameState.Event);
            incidentOccurred = true;
            IncidentManager.Instance?.TriggerIncident(NexusIds.Junctions.J2, IncidentType.Accident, new Vector3(2.5f, 0f, 0f));
            yield return new WaitForSeconds(6f);

            GameManager.Instance?.SetState(GameState.Analysis);
            predictionFired = true;
            _dataProvider.FetchAIPrediction(NexusIds.Junctions.J2, (alert) =>
            {
                EventBus.RaiseAIPrediction(alert);
            });
            yield return new WaitForSeconds(5f);

            GameManager.Instance?.SetState(GameState.Decision);
            recommendationFired = true;
            _dataProvider.FetchStrategies(NexusIds.Junctions.J2, (options) =>
            {
                EventBus.RaiseStrategiesReady(options);
                selectedStrategy = options[0];
            });

            float waitSimM1 = 0f;
            while (!simulationRequested && waitSimM1 < 10f)
            {
                waitSimM1 += Time.deltaTime;
                yield return null;
            }

            if (!simulationRequested)
            {
                EventBus.RaiseSimulateRequested();
            }

            GameManager.Instance?.SetState(GameState.Simulation);
            yield return new WaitForSeconds(3f);

            GameManager.Instance?.SetState(GameState.Comparison);
            _dataProvider.SimulateFutures(NexusIds.Junctions.J2, selectedStrategy.type, (results) =>
            {
                EventBus.RaiseSimulationComplete(results);
            });
            yield return new WaitForSeconds(3f);

            GameManager.Instance?.SetState(GameState.Explanation);
            _dataProvider.FetchExplanation(selectedStrategy.type, (explanation) =>
            {
                EventBus.RaiseExplanationReady(explanation);
            });
            yield return new WaitForSeconds(2.5f);

            GameManager.Instance?.SetState(GameState.Approval);

            float waitApproveM1 = 0f;
            while (!decisionMade && waitApproveM1 < 12f)
            {
                waitApproveM1 += Time.deltaTime;
                yield return null;
            }

            if (!decisionMade)
            {
                EventBus.RaiseApproved();
            }

            if (selectedStrategy.type == StrategyType.DoNothing && approved)
            {
                yield return new WaitForSeconds(4f);
                GameManager.Instance?.SetState(GameState.Failed);
                EventBus.RaiseMissionFailed(new MissionFailureData
                {
                    title = "Network Gridlock",
                    reason = "Unmitigated corridor congestion blocked all approaches. Emergency vehicle failed to reach destination.",
                    finalQueue = 58.5f,
                    ambulanceDelay = 38.2f
                });
                yield break;
            }

            GameManager.Instance?.SetState(GameState.Apply);
            TrafficLightController[] M1Lights = FindObjectsByType<TrafficLightController>(FindObjectsSortMode.None);
            foreach (var light in M1Lights)
            {
                light.ApplyStrategyOverride(selectedStrategy.strategyTypeString, 45f);
            }
            yield return new WaitForSeconds(2f);

            ambulanceDispatched = true;
            _ambulanceAgent = VehicleManager.Instance?.SpawnEmergencyAmbulance();
            yield return new WaitForSeconds(9f);

            GameManager.Instance?.SetState(GameState.Result);
            IncidentManager.Instance?.ResolveIncident(NexusIds.Junctions.J2);
            yield return new WaitForSeconds(4f);

            GameManager.Instance?.SetState(GameState.Score);
            scenarioCompleted = true;

            ScoreBreakdownData scoreDataM1 = new ScoreBreakdownData();
            if (ScoreController.Instance != null)
            {
                scoreDataM1 = new ScoreBreakdownData
                {
                    trafficFlow = ScoreController.Instance.trafficFlowScore,
                    emergencySafety = ScoreController.Instance.emergencySafetyScore,
                    queueControl = ScoreController.Instance.queueControlScore,
                    decisionQuality = ScoreController.Instance.decisionQualityScore
                };
            }
            else
            {
                scoreDataM1 = new ScoreBreakdownData { trafficFlow = 285, emergencySafety = 350, queueControl = 220, decisionQuality = 145 };
            }

            EventBus.RaiseScoreUpdated(scoreDataM1);
            EventBus.RaiseScenarioComplete(scoreDataM1);
        }

        private void HandleStrategySelected(StrategyOptionData option)
        {
            selectedStrategy = option;
            Debug.Log($"[ScenarioDirector] Player selected strategy: {option.label}");

            int mission = (GameManager.Instance != null) ? GameManager.Instance.currentMission : 1;

            if (mission == 2)
            {
                if (option.type != StrategyType.DynamicLane && option.type != StrategyType.DoNothing)
                {
                    float delayDelta = (option.type == StrategyType.EmergencyPriority) ? 15.0f : 10.0f;
                    float emergencyDelta = (option.type == StrategyType.EmergencyPriority) ? -12.4f : -4.4f;
                    string tradeOff = (option.type == StrategyType.EmergencyPriority)
                        ? "Prioritizes immediate ambulance life safety, but overrides the coordinated corridor flow causing civilian gridlock."
                        : "Diverts traffic away from J2, but overloads the downstream bottleneck at J3.";

                    EventBus.RaiseDisagreementTriggered(new DisagreementData
                    {
                        playerAction = option.label,
                        aiRecommendation = "Coordinated Corridor System (optimize network flow)",
                        tradeOffReason = tradeOff,
                        networkDelayDeltaPct = delayDelta,
                        emergencyDelayDeltaS = emergencyDelta
                    });
                }
            }
            else
            {
                if (option.type != aiRecommendedType && option.type != StrategyType.DoNothing)
                {
                    float delayDelta = (option.type == StrategyType.EmergencyPriority) ? 8.0f : -18.0f;
                    float emergencyDelta = (option.type == StrategyType.EmergencyPriority) ? -31.0f : 4.2f;
                    string tradeOff = (option.type == StrategyType.EmergencyPriority)
                        ? "Grants priority green wave to the ambulance at the expense of side-street civilian delay."
                        : "Extends main arterial green times without rerouting incoming bottleneck volume.";

                    EventBus.RaiseDisagreementTriggered(new DisagreementData
                    {
                        playerAction = option.label,
                        aiRecommendation = "Divert Traffic via Cross Street East/West bypass",
                        tradeOffReason = tradeOff,
                        networkDelayDeltaPct = delayDelta,
                        emergencyDelayDeltaS = emergencyDelta
                    });
                }
            }
        }

        private void HandleSimulateRequested()
        {
            simulationRequested = true;
        }

        private void HandleApproved()
        {
            approved = true;
            decisionMade = true;
        }

        private void HandleRejected()
        {
            approved = false;
            decisionMade = true;
        }
    }
}

using System;
using System.Collections;
using System.Text;
using UnityEngine;
using UnityEngine.Networking;
using NexusTwin.Data;
using NexusTwin.Core;

namespace NexusTwin.Networking
{
    public enum ConnectionState
    {
        Disconnected,
        Connecting,
        Connected,
        Error
    }

    /// <summary>
    /// ApiClient — REST API client for communicating with FastAPI backend.
    /// Handles health checks, traffic state polling, AI predictions, and strategy evaluation/application.
    /// Implements Phase J specifications.
    /// </summary>
    public class ApiClient : MonoBehaviour
    {
        public static ApiClient Instance { get; private set; }

        [Header("Backend Configuration")]
        public string baseUrl = "http://localhost:8000";
        public ConnectionState connectionState = ConnectionState.Disconnected;
        public float healthCheckInterval = 5f;
        public int maxRetryAttempts = 3;

        private float _healthTimer = 0f;

        private void Awake()
        {
            if (Instance != null && Instance != this)
            {
                Destroy(gameObject);
                return;
            }
            Instance = this;
        }

        private void Start()
        {
            StartCoroutine(CheckHealthRoutine());
        }

        private void Update()
        {
            _healthTimer += Time.deltaTime;
            if (_healthTimer >= healthCheckInterval)
            {
                _healthTimer = 0f;
                StartCoroutine(CheckHealthRoutine());
            }
        }

        public IEnumerator CheckHealthRoutine(Action<bool> callback = null)
        {
            connectionState = ConnectionState.Connecting;
            using (UnityWebRequest req = UnityWebRequest.Get($"{baseUrl}/health"))
            {
                req.timeout = 3;
                yield return req.SendWebRequest();

                if (req.result == UnityWebRequest.Result.Success)
                {
                    connectionState = ConnectionState.Connected;
                    if (GameManager.Instance != null) GameManager.Instance.isBackendConnected = true;
                    callback?.Invoke(true);
                }
                else
                {
                    connectionState = ConnectionState.Error;
                    if (GameManager.Instance != null) GameManager.Instance.isBackendConnected = false;
                    callback?.Invoke(false);
                }
            }
        }

        public void GetTrafficState(Action<string> onSuccess, Action<string> onError = null)
        {
            StartCoroutine(GetRequestRoutine("/traffic/state", onSuccess, onError));
        }

        public void GetPrediction(string junctionId, Action<string> onSuccess, Action<string> onError = null)
        {
            StartCoroutine(GetRequestRoutine($"/traffic/prediction?junction_id={junctionId}", onSuccess, onError));
        }

        public void GetRecommendation(string junctionId, Action<string> onSuccess, Action<string> onError = null)
        {
            StartCoroutine(GetRequestRoutine($"/recommendation?junction_id={junctionId}", onSuccess, onError));
        }

        public void EvaluateStrategy(int horizonSeconds, string junctionId, string strategyType, float extSec, float divPct, Action<string> onSuccess, Action<string> onError = null)
        {
            string jsonBody = $"{{\"horizon_seconds\": {horizonSeconds}, \"junction_id\": \"{junctionId}\", \"strategy_type\": \"{strategyType}\", \"extension_seconds\": {extSec}, \"diversion_percent\": {divPct}}}";
            StartCoroutine(PostRequestRoutine("/strategy/evaluate", jsonBody, onSuccess, onError));
        }

        public void ApplyStrategy(string strategyId, string strategyType, string junctionId, Action<string> onSuccess, Action<string> onError = null)
        {
            string jsonBody = $"{{\"strategy_id\": \"{strategyId}\", \"strategy_type\": \"{strategyType}\", \"junction_id\": \"{junctionId}\"}}";
            StartCoroutine(PostRequestRoutine("/strategy/apply", jsonBody, onSuccess, onError));
        }

        public void TriggerIncident(string junctionId, string incidentType, Action<string> onSuccess, Action<string> onError = null)
        {
            string jsonBody = $"{{\"junction_id\": \"{junctionId}\", \"incident_type\": \"{incidentType}\", \"severity\": \"high\"}}";
            StartCoroutine(PostRequestRoutine("/incident/trigger", jsonBody, onSuccess, onError));
        }

        private IEnumerator GetRequestRoutine(string endpoint, Action<string> onSuccess, Action<string> onError)
        {
            using (UnityWebRequest req = UnityWebRequest.Get($"{baseUrl}{endpoint}"))
            {
                req.timeout = 4;
                yield return req.SendWebRequest();

                if (req.result == UnityWebRequest.Result.Success)
                {
                    onSuccess?.Invoke(req.downloadHandler.text);
                }
                else
                {
                    onError?.Invoke(req.error);
                }
            }
        }

        private IEnumerator PostRequestRoutine(string endpoint, string jsonPayload, Action<string> onSuccess, Action<string> onError)
        {
            using (UnityWebRequest req = new UnityWebRequest($"{baseUrl}{endpoint}", "POST"))
            {
                byte[] bodyRaw = Encoding.UTF8.GetBytes(jsonPayload);
                req.uploadHandler = new UploadHandlerRaw(bodyRaw);
                req.downloadHandler = new DownloadHandlerBuffer();
                req.SetRequestHeader("Content-Type", "application/json");
                req.timeout = 5;

                yield return req.SendWebRequest();

                if (req.result == UnityWebRequest.Result.Success)
                {
                    onSuccess?.Invoke(req.downloadHandler.text);
                }
                else
                {
                    onError?.Invoke(req.error);
                }
            }
        }
    }
}

