using System;
using System.Collections;
using System.Collections.Generic;
using System.Net.WebSockets;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using UnityEngine;
using NexusTwin.Vehicles;
using NexusTwin.Traffic;
using NexusTwin.Data;

namespace NexusTwin.Networking
{
    [Serializable]
    public class RemoteVehicleData
    {
        public string id;
        public string type;
        public float x;
        public float y;
        public float z;
        public float speed_mps;
        public float angle_deg;
        public string lane_id;
    }

    [Serializable]
    public class RemoteSignalData
    {
        public string junction_id;
        public int phase_index;
        public string phase_state;
        public float remaining_duration_s;
    }

    [Serializable]
    public class RemoteTrafficPacket
    {
        public string type;
        public int step;
        public float timestamp;
        public List<RemoteVehicleData> vehicles;
        public List<RemoteSignalData> signals;
    }

    /// <summary>
    /// WebSocketClient — Real-time telemetry receiver for SUMO/FastAPI bridge.
    /// Streams vehicle coordinates and signal phases directly into Unity scene with smooth interpolation.
    /// Implements Phase J, L specifications.
    /// </summary>
    public class WebSocketClient : MonoBehaviour
    {
        public static WebSocketClient Instance { get; private set; }

        [Header("Connection Settings")]
        public string wsUrl = "ws://localhost:8000/ws/traffic";
        public bool autoConnect = true;
        public bool isConnected = false;
        public float reconnectDelay = 3f;

        private ClientWebSocket _webSocket;
        private CancellationTokenSource _cts;
        private readonly Queue<string> _incomingMessages = new Queue<string>();
        private readonly object _lock = new object();

        private void Awake()
        {
            if (Instance != null && Instance != this)
            {
                Destroy(gameObject);
                return;
            }
            Instance = this;
        }

        private void Start()
        {
            if (autoConnect)
            {
                Connect();
            }
        }

        private void OnDestroy()
        {
            Disconnect();
        }

        private void Update()
        {
            // Process queued network messages on main Unity thread
            lock (_lock)
            {
                while (_incomingMessages.Count > 0)
                {
                    string json = _incomingMessages.Dequeue();
                    ProcessMessage(json);
                }
            }
        }

        public async void Connect()
        {
            if (_webSocket != null && _webSocket.State == WebSocketState.Open) return;

            try
            {
                _cts = new CancellationTokenSource();
                _webSocket = new ClientWebSocket();
                Uri serverUri = new Uri(wsUrl);

                Debug.Log($"[WebSocketClient] Connecting to {wsUrl}...");
                await _webSocket.ConnectAsync(serverUri, _cts.Token);

                if (_webSocket.State == WebSocketState.Open)
                {
                    isConnected = true;
                    Debug.Log("[WebSocketClient] WebSocket connection established successfully");
                    _ = ReceiveLoop();
                }
            }
            catch (Exception ex)
            {
                isConnected = false;
                Debug.LogWarning($"[WebSocketClient] Connection failed: {ex.Message}. Will retry in {reconnectDelay}s");
                Invoke(nameof(Connect), reconnectDelay);
            }
        }

        private async Task ReceiveLoop()
        {
            byte[] buffer = new byte[8192];
            try
            {
                while (_webSocket != null && _webSocket.State == WebSocketState.Open)
                {
                    WebSocketReceiveResult result = await _webSocket.ReceiveAsync(new ArraySegment<byte>(buffer), _cts.Token);
                    if (result.MessageType == WebSocketMessageType.Close)
                    {
                        await _webSocket.CloseAsync(WebSocketCloseStatus.NormalClosure, "Closing", CancellationToken.None);
                        break;
                    }

                    string message = Encoding.UTF8.GetString(buffer, 0, result.Count);
                    lock (_lock)
                    {
                        _incomingMessages.Enqueue(message);
                    }
                }
            }
            catch (Exception ex)
            {
                Debug.LogWarning($"[WebSocketClient] Receive error: {ex.Message}");
            }
            finally
            {
                isConnected = false;
                Invoke(nameof(Connect), reconnectDelay);
            }
        }

        private void ProcessMessage(string json)
        {
            try
            {
                RemoteTrafficPacket packet = JsonUtility.FromJson<RemoteTrafficPacket>(json);
                if (packet == null) return;

                // Sync Vehicles
                if (packet.vehicles != null && VehicleManager.Instance != null)
                {
                    foreach (var vData in packet.vehicles)
                    {
                        VehicleAgent agent = VehicleManager.Instance.GetActiveVehicle(vData.id);
                        if (agent == null)
                        {
                            VehicleType vType = ParseVehicleType(vData.type);
                            agent = VehicleManager.Instance.Spawn(vData.id, vType, null, vType == VehicleType.Ambulance);
                        }

                        Vector3 unityPos = new Vector3(vData.x, vData.y, vData.z);
                        agent.SetRemoteState(unityPos, vData.angle_deg, vData.speed_mps, vData.lane_id);
                    }
                }

                // Sync Signals
                if (packet.signals != null)
                {
                    TrafficLightController[] allLights = FindObjectsByType<TrafficLightController>(FindObjectsSortMode.None);
                    foreach (var sData in packet.signals)
                    {
                        foreach (var light in allLights)
                        {
                            if (light.junctionId == sData.junction_id)
                            {
                                char sigChar = (light.approachIndex < sData.phase_state.Length) ? sData.phase_state[light.approachIndex] : 'r';
                                light.SetSignal(sigChar);
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                Debug.LogWarning($"[WebSocketClient] Parse error: {ex.Message}");
            }
        }

        private VehicleType ParseVehicleType(string typeStr)
        {
            switch (typeStr?.ToLower())
            {
                case "ambulance": return VehicleType.Ambulance;
                case "bus": return VehicleType.Bus;
                case "truck": return VehicleType.Truck;
                case "motorcycle": return VehicleType.Motorcycle;
                case "police": return VehicleType.Police;
                case "fire": return VehicleType.Fire;
                default: return VehicleType.Car;
            }
        }

        public async void Disconnect()
        {
            try
            {
                if (_cts != null)
                {
                    _cts.Cancel();
                    _cts.Dispose();
                    _cts = null;
                }

                if (_webSocket != null)
                {
                    if (_webSocket.State == WebSocketState.Open)
                    {
                        await _webSocket.CloseAsync(WebSocketCloseStatus.NormalClosure, "Client disconnect", CancellationToken.None);
                    }
                    _webSocket.Dispose();
                    _webSocket = null;
                }
            }
            catch (Exception) { }
            finally
            {
                isConnected = false;
            }
        }
    }
}

using UnityEngine;
using NexusTwin.Core;
using NexusTwin.Data;
using NexusTwin.Gameplay;
using NexusTwin.Vehicles;

namespace NexusTwin.Scoring
{
    /// <summary>
    /// ScoreController — Tracks, calculates, and publishes network performance scores.
    /// Evaluates traffic flow, emergency safety, queue reduction, delay reduction, and decision quality.
    /// Implements Phase M specifications.
    /// </summary>
    public class ScoreController : MonoBehaviour
    {
        public static ScoreController Instance { get; private set; }

        [Header("Metric Baselines")]
        public float initialMeanQueue = 35.0f;
        public float initialAvgDelay = 0.28f;

        [Header("Current Live Metrics")]
        public float currentMeanQueue = 35.0f;
        public float currentAvgDelay = 0.28f;
        public float emergencyDelaySeconds = 0.0f;

        [Header("Scores")]
        public int trafficFlowScore = 0;
        public int emergencySafetyScore = 0;
        public int queueControlScore = 0;
        public int decisionQualityScore = 0;

        private void Awake()
        {
            if (Instance != null && Instance != this)
            {
                Destroy(gameObject);
                return;
            }
            Instance = this;
        }

        private void Update()
        {
            if (VehicleManager.Instance != null)
            {
                var active = VehicleManager.Instance.activeVehicles;
                int stoppedCount = 0;
                float totalSpeed = 0f;
                int count = active.Count;

                VehicleAgent ambulance = null;
                for (int i = 0; i < count; i++)
                {
                    var v = active[i];
                    if (v != null)
                    {
                        if (v.isStopped) stoppedCount++;
                        totalSpeed += v.currentSpeed;
                        if (v.vehicleType == VehicleType.Ambulance && v.isEmergency)
                        {
                            ambulance = v;
                        }
                    }
                }

                if (count > 0)
                {
                    currentMeanQueue = stoppedCount * 6.5f;
                    currentAvgDelay = (count - (totalSpeed / 14f)) * 0.1f;
                }

                // Dynamic emergency delays (ambulance blocked)
                if (ambulance != null)
                {
                    if (ambulance.currentSpeed < 2.0f)
                    {
                        emergencyDelaySeconds += Time.deltaTime;
                    }
                }
            }
        }

        private void Start()
        {
            EventBus.OnApproved += CalculatePostApprovalScore;
        }

        private void OnDestroy()
        {
            EventBus.OnApproved -= CalculatePostApprovalScore;
        }

        public ScoreBreakdownData ComputeScore(float delayReductionPct, float queueReductionPct, float emergencyDelay, bool optimalDecision)
        {
            // Traffic Flow: up to 300 pts based on delay reduction
            trafficFlowScore = Mathf.Clamp(Mathf.RoundToInt(200f + delayReductionPct * 3.0f), 50, 350);

            // Emergency Safety: 350 pts if emergency delay is 0, penalized if delayed
            emergencySafetyScore = Mathf.Max(0, Mathf.RoundToInt(350f - emergencyDelay * 20f));

            // Queue Control: up to 250 pts based on queue reduction
            queueControlScore = Mathf.Clamp(Mathf.RoundToInt(150f + queueReductionPct * 2.5f), 20, 280);

            // Decision Quality: 150 pts if player chose the top AI strategy
            decisionQualityScore = optimalDecision ? 150 : 50;

            ScoreBreakdownData breakdown = new ScoreBreakdownData
            {
                trafficFlow = trafficFlowScore,
                emergencySafety = emergencySafetyScore,
                queueControl = queueControlScore,
                decisionQuality = decisionQualityScore
            };

            EventBus.RaiseScoreUpdated(breakdown);
            return breakdown;
        }

        private void CalculatePostApprovalScore()
        {
            if (ScenarioDirector.Instance == null)
            {
                ComputeScore(32.5f, 28.0f, 0.0f, true);
                return;
            }

            int mission = (GameManager.Instance != null) ? GameManager.Instance.currentMission : 1;
            bool approved = ScenarioDirector.Instance.approved;
            StrategyType sType = ScenarioDirector.Instance.selectedStrategy.type;

            if (mission == 2)
            {
                if (!approved)
                {
                    ComputeScore(-65.0f, -78.0f, 32.0f, false);
                }
                else
                {
                    switch (sType)
                    {
                        case StrategyType.DynamicLane:
                            ComputeScore(38.0f, 35.0f, 12.4f, true);
                            break;
                        case StrategyType.EmergencyPriority:
                            ComputeScore(-15.0f, -18.0f, 0.0f, false);
                            break;
                        case StrategyType.Diversion:
                            ComputeScore(-10.0f, -20.0f, 8.0f, false);
                            break;
                        case StrategyType.GreenExtend:
                            ComputeScore(5.0f, -10.0f, 14.8f, false);
                            break;
                        case StrategyType.DoNothing:
                            ComputeScore(-65.0f, -78.0f, 32.0f, false);
                            break;
                        default:
                            ComputeScore(0.0f, 0.0f, 0.0f, false);
                            break;
                    }
                }
            }
            else
            {
                if (!approved)
                {
                    ComputeScore(-45.0f, -62.0f, 24.5f, false);
                }
                else
                {
                    switch (sType)
                    {
                        case StrategyType.Diversion:
                            ComputeScore(32.5f, 28.0f, 0.0f, true);
                            break;
                        case StrategyType.GreenExtend:
                            ComputeScore(18.0f, 15.4f, 4.2f, false);
                            break;
                        case StrategyType.DynamicLane:
                            ComputeScore(6.5f, 4.0f, 6.8f, false);
                            break;
                        case StrategyType.DoNothing:
                            ComputeScore(-45.0f, -62.0f, 24.5f, false);
                            break;
                        default:
                            ComputeScore(0.0f, 0.0f, 0.0f, false);
                            break;
                    }
                }
            }
        }
    }
}

using UnityEngine;
using NexusTwin.Data;

namespace NexusTwin.Traffic
{
    /// <summary>
    /// Junction — Represents one intersection in the 3D world.
    /// junctionId MUST match the backend TrafficState junction_id (J1/J2/J3).
    /// Per PHASE_4 §4.2.
    /// </summary>
    public class Junction : MonoBehaviour
    {
        [Header("Identity — Must match backend exactly")]
        public string junctionId; // "J1", "J2", "J3" — from NexusIds.Junctions

        [Header("Traffic Light Controllers — one per approach")]
        public TrafficLightController[] lights;

        [Header("Queue Visualization Zones")]
        public Transform[] queueZones; // used for vehicle queue density visualization

        [Header("Incident State")]
        public bool hasActiveIncident = false;
        public IncidentType activeIncidentType;

        /// <summary>Update all lights at this junction to a given phase.</summary>
        public void SetPhase(int phaseIndex, string phaseState)
        {
            for (int i = 0; i < lights.Length; i++)
            {
                if (lights[i] != null)
                {
                    // phaseState is SUMO-style string like "GGrrrrGGrrrr"
                    // Each character maps to one signal head
                    char signalChar = (i < phaseState.Length) ? phaseState[i] : 'r';
                    lights[i].SetSignal(signalChar);
                }
            }
        }

        /// <summary>Trigger an incident at this junction.</summary>
        public void TriggerIncident(IncidentType type)
        {
            hasActiveIncident = true;
            activeIncidentType = type;
            Debug.Log($"[Junction {junctionId}] Incident triggered: {type}");
        }

        /// <summary>Clear active incident at this junction.</summary>
        public void ResolveIncident()
        {
            hasActiveIncident = false;
            Debug.Log($"[Junction {junctionId}] Incident resolved");
        }
    }
}

