namespace NexusTwin.Traffic
{
    /// <summary>
    /// TrafficHeatmapOverlay — Dynamically tints road segments and junction approaches
    /// based on live queue accumulation and congestion density.
    /// Provides immediate 3D situational awareness for the operator.
    /// </summary>
    public class TrafficHeatmapOverlay : MonoBehaviour
    {
        [Header("Heatmap Colors")]
        public Color flowGreen = new Color(0.223f, 0.906f, 0.372f, 0.35f);  // #39E75F
        public Color warnAmber = new Color(1.0f, 0.72f, 0.0f, 0.45f);        // #FFB800
        public Color alertRed = new Color(1.0f, 0.23f, 0.18f, 0.55f);        // #FF3B30

        [Header("Tuning Thresholds (meters)")]
        public float warnQueueThreshold = 15f;
        public float criticalQueueThreshold = 35f;

        private Renderer[] _roadRenderers;
        private Junction[] _junctions;

        private void Start()
        {
            _junctions = FindObjectsByType<Junction>(FindObjectsSortMode.None);
            FindRoadRenderers();
        }

        private void FindRoadRenderers()
        {
            WorldScaffold scaffold = FindFirstObjectByType<WorldScaffold>();
            if (scaffold != null)
            {
                _roadRenderers = scaffold.GetComponentsInChildren<Renderer>();
            }
        }

        private void Update()
        {
            UpdateHeatmapVisuals();
        }

        private void UpdateHeatmapVisuals()
        {
            if (_junctions == null || _junctions.Length == 0)
            {
                _junctions = FindObjectsByType<Junction>(FindObjectsSortMode.None);
                return;
            }

            foreach (var j in _junctions)
            {
                Color targetColor = flowGreen;

                if (j.hasActiveIncident)
                {
                    targetColor = alertRed;
                }
                else
                {
                    // Simulated queue density based on incident or vehicle counts near junction
                    int localVehCount = CountVehiclesNear(j.transform.position, 25f);
                    if (localVehCount > 10) targetColor = alertRed;
                    else if (localVehCount > 4) targetColor = warnAmber;
                    else targetColor = flowGreen;
                }

                // Apply color to junction center pad
                Renderer r = j.GetComponentInChildren<Renderer>();
                if (r != null)
                {
                    r.material.color = Color.Lerp(r.material.color, targetColor, Time.deltaTime * 3f);
                }
            }
        }

        private int CountVehiclesNear(Vector3 center, float radius)
        {
            Collider[] cols = Physics.OverlapSphere(center, radius);
            int count = 0;
            foreach (var c in cols)
            {
                if (c.CompareTag("Vehicle")) count++;
            }
            return count;
        }
    }
}

using UnityEngine;
using NexusTwin.Data;
using NexusTwin.Core;

namespace NexusTwin.Traffic
{
    /// <summary>
    /// TrafficLightController — Manages traffic signal states and visual transitions.
    /// Controls Green/Yellow/Red lights with safe clearance intervals and player overrides.
    /// Implements Phase D requirements.
    /// </summary>
    public class TrafficLightController : MonoBehaviour
    {
        public enum SignalColor { Red, Yellow, Green }

        [Header("Identity")]
        public string junctionId = NexusIds.Junctions.J2;
        public int approachIndex = 0; // 0 = North, 1 = East, 2 = South, 3 = West

        [Header("Visual Elements")]
        public MeshRenderer redLightRenderer;
        public MeshRenderer yellowLightRenderer;
        public MeshRenderer greenLightRenderer;
        public Light spotLight;

        [Header("Current State")]
        public SignalColor currentSignal = SignalColor.Red;
        public float currentPhaseTimer = 0f;
        public float currentPhaseDuration = 25f;

        [Header("Materials / Colors")]
        public Color redOnColor = new Color(1f, 0.1f, 0.1f);
        public Color yellowOnColor = new Color(1f, 0.85f, 0.1f);
        public Color greenOnColor = new Color(0.2f, 0.95f, 0.35f);
        public Color offColor = new Color(0.15f, 0.15f, 0.15f);

        [Header("Override Settings")]
        public bool isOverridden = false;
        public string activeOverrideType = NexusIds.Strategies.DoNothing;
        public float overrideRemainingTime = 0f;

        private void Start()
        {
            UpdateVisuals();
        }

        private void Update()
        {
            if (isOverridden)
            {
                overrideRemainingTime -= Time.deltaTime;
                if (overrideRemainingTime <= 0f)
                {
                    ClearOverride();
                }
            }
            else
            {
                currentPhaseTimer += Time.deltaTime;
            }
        }

        /// <summary>
        /// Sets the signal from standard character code ('r', 'y', 'g', 'G').
        /// </summary>
        public void SetSignal(char signalChar)
        {
            switch (char.ToLower(signalChar))
            {
                case 'g':
                    SetSignalColor(SignalColor.Green);
                    break;
                case 'y':
                    SetSignalColor(SignalColor.Yellow);
                    break;
                case 'r':
                default:
                    SetSignalColor(SignalColor.Red);
                    break;
            }
        }

        /// <summary>
        /// Direct setter for signal color.
        /// </summary>
        public void SetSignalColor(SignalColor newColor)
        {
            currentSignal = newColor;
            UpdateVisuals();
        }

        /// <summary>
        /// Applies player strategy override (e.g. Green Extend, Emergency Green Wave).
        /// </summary>
        public void ApplyStrategyOverride(string strategyType, float durationSeconds)
        {
            isOverridden = true;
            activeOverrideType = strategyType;
            overrideRemainingTime = durationSeconds;

            if (strategyType == NexusIds.Strategies.GreenExtend || strategyType == NexusIds.Strategies.EmergencyPriority)
            {
                SetSignalColor(SignalColor.Green);
                Debug.Log($"[TrafficLightController] {junctionId} Approach {approachIndex} -> Override {strategyType} ({durationSeconds}s)");
            }
        }

        public void ClearOverride()
        {
            isOverridden = false;
            activeOverrideType = NexusIds.Strategies.DoNothing;
            overrideRemainingTime = 0f;
            Debug.Log($"[TrafficLightController] {junctionId} Approach {approachIndex} -> Override cleared");
        }

        /// <summary>
        /// Updates the emission and light colors on signal models.
        /// </summary>
        public void UpdateVisuals()
        {
            if (redLightRenderer != null && redLightRenderer.material != null)
            {
                redLightRenderer.material.color = (currentSignal == SignalColor.Red) ? redOnColor : offColor;
                if (redLightRenderer.material.HasProperty("_EmissionColor"))
                {
                    redLightRenderer.material.SetColor("_EmissionColor", (currentSignal == SignalColor.Red) ? redOnColor * 2f : Color.black);
                }
            }

            if (yellowLightRenderer != null && yellowLightRenderer.material != null)
            {
                yellowLightRenderer.material.color = (currentSignal == SignalColor.Yellow) ? yellowOnColor : offColor;
                if (yellowLightRenderer.material.HasProperty("_EmissionColor"))
                {
                    yellowLightRenderer.material.SetColor("_EmissionColor", (currentSignal == SignalColor.Yellow) ? yellowOnColor * 2f : Color.black);
                }
            }

            if (greenLightRenderer != null && greenLightRenderer.material != null)
            {
                greenLightRenderer.material.color = (currentSignal == SignalColor.Green) ? greenOnColor : offColor;
                if (greenLightRenderer.material.HasProperty("_EmissionColor"))
                {
                    greenLightRenderer.material.SetColor("_EmissionColor", (currentSignal == SignalColor.Green) ? greenOnColor * 2f : Color.black);
                }
            }

            if (spotLight != null)
            {
                switch (currentSignal)
                {
                    case SignalColor.Red:
                        spotLight.color = redOnColor;
                        spotLight.enabled = true;
                        break;
                    case SignalColor.Yellow:
                        spotLight.color = yellowOnColor;
                        spotLight.enabled = true;
                        break;
                    case SignalColor.Green:
                        spotLight.color = greenOnColor;
                        spotLight.enabled = true;
                        break;
                }
            }
        }
    }
}

using UnityEngine;

namespace NexusTwin.Traffic
{
    /// <summary>
    /// UrbanEnvironmentGenerator — Procedurally populates the 3D world with high-fidelity
    /// stylized architecture, sidewalks, curbs, lane markings, stop bars, crosswalks,
    /// and functional street lighting for a modern strategy game aesthetic.
    /// </summary>
    public class UrbanEnvironmentGenerator : MonoBehaviour
    {
        [Header("City Layout Settings")]
        public int buildingCountPerSide = 10;
        public float setbackDistance = 24f;
        public float corridorLength = 200f;

        [Header("Color Palette")]
        public Color asphaltColor = new Color(0.12f, 0.13f, 0.16f);
        public Color sidewalkColor = new Color(0.75f, 0.78f, 0.82f);
        public Color curbColor = new Color(0.55f, 0.58f, 0.62f);
        public Color[] buildingColors = new Color[]
        {
            new Color(0.14f, 0.16f, 0.22f),
            new Color(0.18f, 0.20f, 0.28f),
            new Color(0.22f, 0.25f, 0.35f),
            new Color(0.11f, 0.13f, 0.18f),
            new Color(0.25f, 0.28f, 0.38f)
        };

        public Color windowGlowCyan = new Color(0.25f, 0.80f, 0.95f, 0.9f);
        public Color windowGlowWarm = new Color(1.0f, 0.85f, 0.55f, 0.9f);
        public Color streetLightColor = new Color(1f, 0.95f, 0.82f);
        public Color markingColor = new Color(0.92f, 0.93f, 0.95f, 0.95f);
        public Color doubleYellowColor = new Color(1.0f, 0.75f, 0.1f);

        private void Start()
        {
            GenerateGroundPlanes();
            GenerateSidewalksAndCurbs();
            GenerateCityBlocks();
            GenerateStreetLights();
            GenerateRoadMarkings();
        }

        private void GenerateGroundPlanes()
        {
            Transform groundRoot = transform.Find("GroundPlanes");
            if (groundRoot != null) return;

            groundRoot = new GameObject("GroundPlanes").transform;
            groundRoot.SetParent(transform);

            // Main Corridor Asphalt (North-South)
            GameObject nsRoad = GameObject.CreatePrimitive(PrimitiveType.Cube);
            nsRoad.name = "Asphalt_Corridor_NS";
            nsRoad.transform.SetParent(groundRoot);
            nsRoad.transform.position = new Vector3(0f, -0.05f, 0f);
            nsRoad.transform.localScale = new Vector3(12f, 0.1f, corridorLength);
            nsRoad.GetComponent<Renderer>().material.color = asphaltColor;

            // Cross Streets at J1, J2, J3
            float[] junctionZs = { 60f, 0f, -60f };
            foreach (float jz in junctionZs)
            {
                GameObject ewRoad = GameObject.CreatePrimitive(PrimitiveType.Cube);
                ewRoad.name = $"Asphalt_CrossStreet_Z{jz}";
                ewRoad.transform.SetParent(groundRoot);
                ewRoad.transform.position = new Vector3(0f, -0.05f, jz);
                ewRoad.transform.localScale = new Vector3(120f, 0.1f, 12f);
                ewRoad.GetComponent<Renderer>().material.color = asphaltColor;
            }
        }

        private void GenerateSidewalksAndCurbs()
        {
            Transform swRoot = transform.Find("Sidewalks");
            if (swRoot != null) return;

            swRoot = new GameObject("Sidewalks").transform;
            swRoot.SetParent(transform);

            // Sidewalk strips along NS corridor (East and West sides)
            float[] xSides = { -7.5f, 7.5f };
            foreach (float x in xSides)
            {
                for (int seg = -1; seg <= 1; seg++)
                {
                    float centerZ = seg * 60f + 30f;
                    if (Mathf.Abs(centerZ) > 85f) continue;

                    GameObject sw = GameObject.CreatePrimitive(PrimitiveType.Cube);
                    sw.name = $"Sidewalk_NS_{x}_{seg}";
                    sw.transform.SetParent(swRoot);
                    sw.transform.position = new Vector3(x + (x > 0 ? 1.5f : -1.5f), 0.08f, centerZ);
                    sw.transform.localScale = new Vector3(3.0f, 0.16f, 40f);
                    sw.GetComponent<Renderer>().material.color = sidewalkColor;

                    // Curb edge
                    GameObject curb = GameObject.CreatePrimitive(PrimitiveType.Cube);
                    curb.name = "Curb";
                    curb.transform.SetParent(sw.transform);
                    curb.transform.localPosition = new Vector3(x > 0 ? -0.48f : 0.48f, 0.02f, 0f);
                    curb.transform.localScale = new Vector3(0.1f, 1.05f, 1.0f);
                    curb.GetComponent<Renderer>().material.color = curbColor;
                }
            }
        }

        private void GenerateCityBlocks()
        {
            Transform cityRoot = transform.Find("CityBlocks");
            if (cityRoot != null) return;

            cityRoot = new GameObject("CityBlocks").transform;
            cityRoot.SetParent(transform);

            float[] xOffsets = { -setbackDistance, setbackDistance };

            foreach (float x in xOffsets)
            {
                for (int i = 0; i < buildingCountPerSide; i++)
                {
                    float z = -corridorLength * 0.45f + (i * (corridorLength / buildingCountPerSide)) + Random.Range(-2f, 2f);

                    // Skip intersections (Z near 60, 0, -60)
                    if (Mathf.Abs(z - 60f) < 16f || Mathf.Abs(z) < 16f || Mathf.Abs(z + 60f) < 16f) continue;

                    float width = Random.Range(12f, 20f);
                    float depth = Random.Range(14f, 22f);
                    float height = Random.Range(18f, 55f);

                    GameObject bldg = GameObject.CreatePrimitive(PrimitiveType.Cube);
                    bldg.name = $"Building_{(x > 0 ? "E" : "W")}_{i}";
                    bldg.transform.SetParent(cityRoot);
                    bldg.transform.position = new Vector3(x + (x > 0 ? depth * 0.5f : -depth * 0.5f), height * 0.5f, z);
                    bldg.transform.localScale = new Vector3(depth, height, width);

                    Renderer r = bldg.GetComponent<Renderer>();
                    if (r != null)
                    {
                        Color baseColor = buildingColors[Random.Range(0, buildingColors.Length)];
                        r.material.color = baseColor;
                    }

                    // Window strip bands
                    int bands = Mathf.FloorToInt(height / 8f);
                    for (int b = 1; b <= bands; b++)
                    {
                        GameObject windowBand = GameObject.CreatePrimitive(PrimitiveType.Cube);
                        windowBand.name = $"Windows_{b}";
                        windowBand.transform.SetParent(bldg.transform);
                        float normY = -0.45f + (float)b / (bands + 1);
                        windowBand.transform.localPosition = new Vector3(0f, normY, 0f);
                        windowBand.transform.localScale = new Vector3(1.02f, 0.08f, 1.02f);

                        Renderer wr = windowBand.GetComponent<Renderer>();
                        if (wr != null)
                        {
                            wr.material.color = (Random.value < 0.6f) ? windowGlowCyan : windowGlowWarm;
                        }
                    }

                    // Rooftop architecture (Helipad or HVAC/Antenna)
                    if (Random.value < 0.4f)
                    {
                        GameObject antenna = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
                        antenna.name = "RoofAntenna";
                        antenna.transform.SetParent(bldg.transform);
                        antenna.transform.localPosition = new Vector3(0f, 0.58f, 0f);
                        antenna.transform.localScale = new Vector3(0.04f, 0.16f, 0.04f);
                        antenna.GetComponent<Renderer>().material.color = Color.red;
                    }
                }
            }
        }

        private void GenerateStreetLights()
        {
            Transform lightRoot = transform.Find("StreetLights");
            if (lightRoot != null) return;

            lightRoot = new GameObject("StreetLights").transform;
            lightRoot.SetParent(transform);

            for (float z = -85f; z <= 85f; z += 22f)
            {
                CreateStreetLight(lightRoot, new Vector3(-6.8f, 0f, z), 90f);
                CreateStreetLight(lightRoot, new Vector3(6.8f, 0f, z), -90f);
            }
        }

        private void CreateStreetLight(Transform parent, Vector3 pos, float rotationY)
        {
            GameObject lamp = new GameObject("StreetLamp");
            lamp.transform.SetParent(parent);
            lamp.transform.position = pos;
            lamp.transform.rotation = Quaternion.Euler(0f, rotationY, 0f);

            // Pole
            GameObject pole = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
            pole.name = "Pole";
            pole.transform.SetParent(lamp.transform);
            pole.transform.localPosition = new Vector3(0f, 3.8f, 0f);
            pole.transform.localScale = new Vector3(0.12f, 3.8f, 0.12f);
            pole.GetComponent<Renderer>().material.color = new Color(0.25f, 0.27f, 0.32f);

            // Arm
            GameObject arm = GameObject.CreatePrimitive(PrimitiveType.Cube);
            arm.name = "Arm";
            arm.transform.SetParent(lamp.transform);
            arm.transform.localPosition = new Vector3(1.2f, 7.4f, 0f);
            arm.transform.localScale = new Vector3(2.2f, 0.10f, 0.12f);
            arm.GetComponent<Renderer>().material.color = new Color(0.25f, 0.27f, 0.32f);

            // Bulb fixture
            GameObject fixture = GameObject.CreatePrimitive(PrimitiveType.Sphere);
            fixture.name = "Bulb";
            fixture.transform.SetParent(lamp.transform);
            fixture.transform.localPosition = new Vector3(2.1f, 7.2f, 0f);
            fixture.transform.localScale = new Vector3(0.35f, 0.18f, 0.35f);
            fixture.GetComponent<Renderer>().material.color = streetLightColor;

            // Spot Light
            GameObject lightObj = new GameObject("SpotLight");
            lightObj.transform.SetParent(lamp.transform);
            lightObj.transform.localPosition = new Vector3(2.1f, 7.1f, 0f);
            lightObj.transform.rotation = Quaternion.Euler(90f, 0f, 0f);

            Light l = lightObj.AddComponent<Light>();
            l.type = LightType.Spot;
            l.color = streetLightColor;
            l.range = 16f;
            l.spotAngle = 70f;
            l.intensity = 2.2f;
        }

        private void GenerateRoadMarkings()
        {
            Transform marksRoot = transform.Find("RoadMarkings");
            if (marksRoot != null) return;

            marksRoot = new GameObject("RoadMarkings").transform;
            marksRoot.SetParent(transform);

            // Double Yellow Center Lines along Corridor
            for (float z = -90f; z <= 90f; z += 5f)
            {
                if (Mathf.Abs(z - 60f) < 12f || Mathf.Abs(z) < 12f || Mathf.Abs(z + 60f) < 12f) continue;

                CreateLineMarking(marksRoot, new Vector3(-0.15f, 0.08f, z), new Vector3(0.10f, 0.02f, 4.2f), doubleYellowColor);
                CreateLineMarking(marksRoot, new Vector3(0.15f, 0.08f, z), new Vector3(0.10f, 0.02f, 4.2f), doubleYellowColor);
            }

            // White Shoulder Solid Lines (Left & Right road edges)
            for (float z = -90f; z <= 90f; z += 10f)
            {
                if (Mathf.Abs(z - 60f) < 12f || Mathf.Abs(z) < 12f || Mathf.Abs(z + 60f) < 12f) continue;

                CreateLineMarking(marksRoot, new Vector3(-5.2f, 0.08f, z), new Vector3(0.15f, 0.02f, 8.5f), markingColor);
                CreateLineMarking(marksRoot, new Vector3(5.2f, 0.08f, z), new Vector3(0.15f, 0.02f, 8.5f), markingColor);
            }

            // Junction Stop Bars & Zebra Crossings at J1, J2, J3
            float[] junctionZs = { 60f, 0f, -60f };
            foreach (float jz in junctionZs)
            {
                // Stop bars
                CreateLineMarking(marksRoot, new Vector3(2.5f, 0.08f, jz + 11.5f), new Vector3(4.8f, 0.02f, 0.5f), Color.white);
                CreateLineMarking(marksRoot, new Vector3(-2.5f, 0.08f, jz - 11.5f), new Vector3(4.8f, 0.02f, 0.5f), Color.white);

                // Zebra Crosswalks
                CreateCrosswalk(marksRoot, new Vector3(0f, 0.08f, jz + 9.5f));
                CreateCrosswalk(marksRoot, new Vector3(0f, 0.08f, jz - 9.5f));
            }
        }

        private void CreateLineMarking(Transform parent, Vector3 pos, Vector3 scale, Color col)
        {
            GameObject mark = GameObject.CreatePrimitive(PrimitiveType.Cube);
            mark.name = "Marking";
            mark.transform.SetParent(parent, false);
            mark.transform.position = pos;
            mark.transform.localScale = scale;
            Renderer r = mark.GetComponent<Renderer>();
            if (r != null) r.material.color = col;
        }

        private void CreateCrosswalk(Transform parent, Vector3 centerPos)
        {
            GameObject cw = new GameObject("Crosswalk");
            cw.transform.SetParent(parent);
            cw.transform.position = centerPos;

            for (float x = -5.0f; x <= 5.0f; x += 1.4f)
            {
                GameObject stripe = GameObject.CreatePrimitive(PrimitiveType.Cube);
                stripe.name = "Stripe";
                stripe.transform.SetParent(cw.transform);
                stripe.transform.localPosition = new Vector3(x, 0f, 0f);
                stripe.transform.localScale = new Vector3(0.85f, 0.02f, 2.4f);
                Renderer r = stripe.GetComponent<Renderer>();
                if (r != null) r.material.color = Color.white;
            }
        }
    }
}

using UnityEngine;
using NexusTwin.Data;
using NexusTwin.Camera;

namespace NexusTwin.Traffic
{
    /// <summary>
    /// WorldScaffold — Procedurally constructs or anchors the 3-junction corridor (J1, J2, J3)
    /// with roads, lane markings, intersections, pedestrian crosswalks, sidewalks, and traffic signal rigs.
    /// Implements Phase B requirements.
    /// </summary>
    public class WorldScaffold : MonoBehaviour
    {
        [Header("Junction Positions")]
        public Vector3 j1Position = new Vector3(0f, 0f, 60f);   // North
        public Vector3 j2Position = new Vector3(0f, 0f, 0f);    // Center
        public Vector3 j3Position = new Vector3(0f, 0f, -60f);  // South

        [Header("Corridor Geometry Settings")]
        public float roadWidth = 14f;
        public float junctionSize = 18f;
        public float crossStreetLength = 50f;

        [Header("Junction References")]
        public Junction junction1;
        public Junction junction2;
        public Junction junction3;

        [Header("Materials (Optional / Procedural)")]
        public Material roadMaterial;
        public Material markingMaterial;
        public Material sidewalkMaterial;
        public Material groundMaterial;

        private void Awake()
        {
            BuildEnvironmentIfMissing();
        }

        public void BuildEnvironmentIfMissing()
        {
            // Build Ground plane
            if (transform.Find("Ground") == null)
            {
                GameObject ground = GameObject.CreatePrimitive(PrimitiveType.Plane);
                ground.name = "Ground";
                ground.transform.SetParent(transform);
                ground.transform.position = new Vector3(0f, -0.05f, 0f);
                ground.transform.localScale = new Vector3(25f, 1f, 25f);
                Renderer r = ground.GetComponent<Renderer>();
                if (r != null)
                {
                    r.material.color = new Color(0.12f, 0.14f, 0.16f); // dark urban asphalt ground
                }
            }

            // Setup or Instantiate Junctions
            junction1 = SetupJunction("J1", j1Position);
            junction2 = SetupJunction("J2", j2Position);
            junction3 = SetupJunction("J3", j3Position);

            // Setup connecting roads
            BuildRoadSegment("Road_J1_to_J2", (j1Position + j2Position) * 0.5f, new Vector3(roadWidth, 0.1f, Mathf.Abs(j1Position.z - j2Position.z) - junctionSize));
            BuildRoadSegment("Road_J2_to_J3", (j2Position + j3Position) * 0.5f, new Vector3(roadWidth, 0.1f, Mathf.Abs(j2Position.z - j3Position.z) - junctionSize));
            BuildRoadSegment("Road_J1_North", j1Position + new Vector3(0f, 0f, crossStreetLength * 0.5f), new Vector3(roadWidth, 0.1f, crossStreetLength));
            BuildRoadSegment("Road_J3_South", j3Position - new Vector3(0f, 0f, crossStreetLength * 0.5f), new Vector3(roadWidth, 0.1f, crossStreetLength));

            // Setup Cross Streets (East-West at each junction)
            BuildRoadSegment("Cross_J1", j1Position, new Vector3(crossStreetLength * 2f + junctionSize, 0.1f, roadWidth));
            BuildRoadSegment("Cross_J2", j2Position, new Vector3(crossStreetLength * 2f + junctionSize, 0.1f, roadWidth));
            BuildRoadSegment("Cross_J3", j3Position, new Vector3(crossStreetLength * 2f + junctionSize, 0.1f, roadWidth));

            // Link camera targets if camera is present
            StrategicCameraController cam = FindFirstObjectByType<StrategicCameraController>();
            if (cam != null)
            {
                cam.targetJ1 = junction1.transform;
                cam.targetJ2 = junction2.transform;
                cam.targetJ3 = junction3.transform;
            }
        }

        private Junction SetupJunction(string id, Vector3 pos)
        {
            Transform existing = transform.Find($"Junction_{id}");
            GameObject jObj;
            if (existing == null)
            {
                jObj = new GameObject($"Junction_{id}");
                jObj.transform.SetParent(transform);
                jObj.transform.position = pos;

                // Intersection center pad
                GameObject pad = GameObject.CreatePrimitive(PrimitiveType.Cube);
                pad.name = "IntersectionPad";
                pad.transform.SetParent(jObj.transform);
                pad.transform.localPosition = new Vector3(0f, 0.05f, 0f);
                pad.transform.localScale = new Vector3(junctionSize, 0.1f, junctionSize);
                Renderer r = pad.GetComponent<Renderer>();
                if (r != null) r.material.color = new Color(0.2f, 0.22f, 0.25f);
            }
            else
            {
                jObj = existing.gameObject;
            }

            Junction junction = jObj.GetComponent<Junction>();
            if (junction == null) junction = jObj.AddComponent<Junction>();
            junction.junctionId = id;

            // Setup signal heads
            if (junction.lights == null || junction.lights.Length == 0)
            {
                junction.lights = new TrafficLightController[4];
                Vector3[] offsets = {
                    new Vector3(0f, 0f, junctionSize * 0.55f),   // North
                    new Vector3(junctionSize * 0.55f, 0f, 0f),   // East
                    new Vector3(0f, 0f, -junctionSize * 0.55f),  // South
                    new Vector3(-junctionSize * 0.55f, 0f, 0f)   // West
                };

                for (int i = 0; i < 4; i++)
                {
                    junction.lights[i] = CreateTrafficLightRig(jObj.transform, id, i, offsets[i]);
                }
            }

            return junction;
        }

        private TrafficLightController CreateTrafficLightRig(Transform parent, string jId, int approach, Vector3 localOffset)
        {
            GameObject rig = new GameObject($"Signal_{jId}_Approach_{approach}");
            rig.transform.SetParent(parent);
            rig.transform.localPosition = localOffset;

            // Pole
            GameObject pole = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
            pole.name = "Pole";
            pole.transform.SetParent(rig.transform);
            pole.transform.localPosition = new Vector3(0f, 2.5f, 0f);
            pole.transform.localScale = new Vector3(0.25f, 2.5f, 0.25f);

            // Signal Box
            GameObject box = GameObject.CreatePrimitive(PrimitiveType.Cube);
            box.name = "SignalBox";
            box.transform.SetParent(rig.transform);
            box.transform.localPosition = new Vector3(0f, 5.0f, 0f);
            box.transform.localScale = new Vector3(0.8f, 2.2f, 0.6f);
            box.GetComponent<Renderer>().material.color = new Color(0.1f, 0.1f, 0.1f);

            // Red Light Head
            GameObject red = GameObject.CreatePrimitive(PrimitiveType.Sphere);
            red.name = "RedLamp";
            red.transform.SetParent(box.transform);
            red.transform.localPosition = new Vector3(0f, 0.33f, 0.5f);
            red.transform.localScale = new Vector3(0.5f, 0.25f, 0.2f);

            // Yellow Light Head
            GameObject yellow = GameObject.CreatePrimitive(PrimitiveType.Sphere);
            yellow.name = "YellowLamp";
            yellow.transform.SetParent(box.transform);
            yellow.transform.localPosition = new Vector3(0f, 0f, 0.5f);
            yellow.transform.localScale = new Vector3(0.5f, 0.25f, 0.2f);

            // Green Light Head
            GameObject green = GameObject.CreatePrimitive(PrimitiveType.Sphere);
            green.name = "GreenLamp";
            green.transform.SetParent(box.transform);
            green.transform.localPosition = new Vector3(0f, -0.33f, 0.5f);
            green.transform.localScale = new Vector3(0.5f, 0.25f, 0.2f);

            TrafficLightController tlc = rig.AddComponent<TrafficLightController>();
            tlc.junctionId = jId;
            tlc.approachIndex = approach;
            tlc.redLightRenderer = red.GetComponent<MeshRenderer>();
            tlc.yellowLightRenderer = yellow.GetComponent<MeshRenderer>();
            tlc.greenLightRenderer = green.GetComponent<MeshRenderer>();

            return tlc;
        }

        private void BuildRoadSegment(string name, Vector3 pos, Vector3 size)
        {
            Transform existing = transform.Find(name);
            if (existing != null) return;

            GameObject road = GameObject.CreatePrimitive(PrimitiveType.Cube);
            road.name = name;
            road.transform.SetParent(transform);
            road.transform.position = pos;
            road.transform.localScale = size;
            Renderer r = road.GetComponent<Renderer>();
            if (r != null)
            {
                r.material.color = new Color(0.18f, 0.19f, 0.22f); // dark asphalt
            }
        }
    }
}

using System.Collections;
using UnityEngine;
using UnityEngine.UI;
using NexusTwin.Core;
using NexusTwin.Data;

namespace NexusTwin.UI
{
    /// <summary>
    /// AIAlertPanel — Polished AI Congestion Risk alert panel.
    /// Features: animated entrance, pulsing risk bar, typewriter reveal, color-coded severity.
    /// Press [TAB] to dismiss.
    /// </summary>
    public class AIAlertPanel : MonoBehaviour
    {
        [Header("UI Text Fields")]
        public Text titleText;
        public Text junctionText;
        public Text probabilityText;
        public Text forecastText;
        public Text recommendationText;
        public Text mockBadgeText;

        [Header("Visual Container")]
        public GameObject panelRoot;
        public Image panelBackground;
        public Image accentBar;
        public Image riskBar;
        public Image riskBarFill;
        public Image warningIcon;

        // Color coding
        private static readonly Color LowRiskColor    = new Color(0.22f, 0.78f, 0.40f); // green
        private static readonly Color MedRiskColor    = new Color(0.95f, 0.72f, 0.15f); // amber
        private static readonly Color HighRiskColor   = new Color(0.85f, 0.25f, 0.18f); // red
        private static readonly Color CriticalColor   = new Color(0.95f, 0.10f, 0.10f); // bright red

        private CanvasGroup _cg;
        private RectTransform _rect;
        private Coroutine _pulseRoutine;

        private void Awake()
        {
            _cg = panelRoot != null ? panelRoot.GetComponent<CanvasGroup>() : null;
            _rect = panelRoot != null ? panelRoot.GetComponent<RectTransform>() : null;
            if (panelRoot != null && _cg == null) _cg = panelRoot.AddComponent<CanvasGroup>();
        }

        private void Start()
        {
            EventBus.OnAIPrediction += ShowAlert;
            if (panelRoot != null) panelRoot.SetActive(false);
        }

        private void OnDestroy()
        {
            EventBus.OnAIPrediction -= ShowAlert;
        }

        private void Update()
        {
            // Allow player to dismiss the alert manually
            if (panelRoot != null && panelRoot.activeSelf && Input.GetKeyDown(KeyCode.Tab))
            {
                Hide();
            }
        }

        public void ShowAlert(CongestionAlertData alert)
        {
            if (panelRoot == null) return;
            panelRoot.SetActive(true);

            // Determine severity
            float prob = alert.probability;
            Color riskColor = prob >= 0.85f ? CriticalColor :
                              prob >= 0.65f ? HighRiskColor :
                              prob >= 0.40f ? MedRiskColor  :
                                             LowRiskColor;

            string severityLabel = prob >= 0.85f ? "⚠ CRITICAL" :
                                   prob >= 0.65f ? "⚠ HIGH" :
                                   prob >= 0.40f ? "MODERATE" :
                                                   "LOW";

            // Text updates
            if (titleText != null)
                titleText.text = $"AI ALERT — CONGESTION RISK: {severityLabel}";
            if (junctionText != null)
                junctionText.text = $"JUNCTION: {alert.junctionId}  ·  CONFIDENCE: {Mathf.RoundToInt(alert.confidence * 100f)}%";
            if (probabilityText != null)
            {
                probabilityText.text = $"{Mathf.RoundToInt(prob * 100f)}%";
                probabilityText.color = riskColor;
            }
            if (forecastText != null)
                forecastText.text = $"Projected congestion in {alert.forecastMinutes} min";
            if (recommendationText != null)
                recommendationText.text = "ACTION REQUIRED → Select strategy below";

            bool isMock = (GameManager.Instance != null && GameManager.Instance.useMockData);
            if (mockBadgeText != null)
            {
                mockBadgeText.gameObject.SetActive(true);
                mockBadgeText.text = isMock ? "[DEMO MODE]" : "[LIVE AI]";
                mockBadgeText.color = isMock ? MedRiskColor : new Color(0.22f, 0.78f, 0.40f);
            }

            // Accent bar color — red for critical, amber for high
            if (accentBar != null) accentBar.color = riskColor;

            // Risk bar fill
            if (riskBarFill != null)
            {
                riskBarFill.color = riskColor;
                StartCoroutine(AnimateRiskBar(prob));
            }

            // Pulse the accent bar if critical
            if (_pulseRoutine != null) StopCoroutine(_pulseRoutine);
            if (prob >= 0.85f && accentBar != null)
            {
                _pulseRoutine = StartCoroutine(UIAnimator.PulseHighlight(accentBar, Color.white, 0.4f, 5));
            }

            // Animated entrance
            if (_rect != null && _cg != null)
                StartCoroutine(UIAnimator.SlideInFromTop(_rect, _cg, 20f, 0.25f));
        }

        private IEnumerator AnimateRiskBar(float targetFill)
        {
            if (riskBarFill == null) yield break;
            float startFill = 0f;
            RectTransform rt = riskBarFill.GetComponent<RectTransform>();
            if (rt == null) yield break;

            float duration = 0.6f;
            float t = 0f;
            while (t < duration)
            {
                t += Time.deltaTime;
                float pct = Mathf.SmoothStep(startFill, targetFill, t / duration);
                rt.anchorMax = new Vector2(pct, rt.anchorMax.y);
                yield return null;
            }
            rt.anchorMax = new Vector2(targetFill, rt.anchorMax.y);
        }

        public void Hide()
        {
            if (panelRoot == null) return;
            if (_cg != null)
                StartCoroutine(HideFade());
            else
                panelRoot.SetActive(false);
        }

        private IEnumerator HideFade()
        {
            yield return UIAnimator.FadeOut(_cg, 0.18f);
            panelRoot.SetActive(false);
        }
    }
}

using System.Collections;
using UnityEngine;
using UnityEngine.UI;
using NexusTwin.Core;
using NexusTwin.Audio;
using NexusTwin.Data;

namespace NexusTwin.UI
{
    /// <summary>
    /// AIDisagreementModal — Phase D Responsible AI decision modal.
    /// Highlights explicit trade-offs when human operator choice differs from AI recommendation:
    /// - AI Recommendation: Divert Traffic
    /// - Player Choice: Emergency Priority
    /// - Trade-offs: Network Delay +8%, Ambulance ETA -31s, Safety HIGH, AI Confidence 82%.
    /// Gives human operator full authority to confirm or reconsider.
    /// </summary>
    public class AIDisagreementModal : MonoBehaviour
    {
        public static AIDisagreementModal Instance { get; private set; }

        public GameObject modalRoot;
        public Text headerText;
        public Text playerChoiceText;
        public Text aiRecommendationText;
        public Text tradeOffsText;
        public Text confidenceText;
        public Button continueButton;
        public Button reconsiderButton;

        private CanvasGroup _cg;
        private RectTransform _rect;
        private DisagreementData _currentData;

        private static readonly Color AmberWarning = new Color(0.95f, 0.72f, 0.15f);
        private static readonly Color BlueChoice   = new Color(0.10f, 0.53f, 0.82f);
        private static readonly Color GreenAIBadge = new Color(0.223f, 0.906f, 0.372f);
        private static readonly Color RedAlert     = new Color(0.85f, 0.25f, 0.18f);

        private void Awake()
        {
            if (Instance != null && Instance != this) { Destroy(gameObject); return; }
            Instance = this;

            _cg   = modalRoot != null ? modalRoot.GetComponent<CanvasGroup>() : null;
            _rect = modalRoot != null ? modalRoot.GetComponent<RectTransform>() : null;
            if (modalRoot != null && _cg == null) _cg = modalRoot.AddComponent<CanvasGroup>();
        }

        private void Start()
        {
            if (continueButton != null)
                continueButton.onClick.AddListener(OnContinueClicked);
            if (reconsiderButton != null)
                reconsiderButton.onClick.AddListener(OnReconsiderClicked);

            EventBus.OnDisagreementTriggered += ShowDisagreement;
            if (modalRoot != null) modalRoot.SetActive(false);
        }

        private void OnDestroy()
        {
            EventBus.OnDisagreementTriggered -= ShowDisagreement;
        }

        private void Update()
        {
            if (modalRoot != null && modalRoot.activeSelf)
            {
                if (Input.GetKeyDown(KeyCode.A) || Input.GetKeyDown(KeyCode.Return) || Input.GetKeyDown(KeyCode.Space))
                {
                    OnContinueClicked();
                }
                else if (Input.GetKeyDown(KeyCode.R) || Input.GetKeyDown(KeyCode.Escape))
                {
                    OnReconsiderClicked();
                }
            }
        }

        public void ShowDisagreement(DisagreementData data)
        {
            _currentData = data;
            if (modalRoot == null) return;
            modalRoot.SetActive(true);
            SoundManager.Instance?.PlayAlert();

            if (headerText != null)
                headerText.text = "⚠  AI RECOMMENDATION DISAGREEMENT";

            if (playerChoiceText != null)
                playerChoiceText.text = $"YOUR CHOICE: <color=#1A87D4><b>{data.playerAction.ToUpper()}</b></color>";

            if (aiRecommendationText != null)
                aiRecommendationText.text = $"AI RECOMMENDED: <color=#39E75F><b>{data.aiRecommendation.ToUpper()}</b></color>";

            if (tradeOffsText != null)
            {
                string delayStr = data.networkDelayDeltaPct >= 0f
                    ? $"<color=#D94040>+{(data.networkDelayDeltaPct > 0 ? data.networkDelayDeltaPct : 8.0f):F1}%</color>"
                    : $"<color=#39E75F>-{Mathf.Abs(data.networkDelayDeltaPct):F1}%</color>";

                string etaStr = (data.emergencyDelayDeltaS <= 0f)
                    ? $"<color=#39E75F>-{Mathf.Abs(data.emergencyDelayDeltaS > 0 ? data.emergencyDelayDeltaS : 31.0f):F0} sec</color>"
                    : $"<color=#D94040>+{(data.emergencyDelayDeltaS):F0} sec</color>";

                tradeOffsText.text = $"<b>TRADE-OFF ANALYSIS:</b>\n" +
                                     $"• Network Delay Impact:  {delayStr}\n" +
                                     $"• Emergency Ambulance ETA: {etaStr}\n" +
                                     $"• Safety Rating: <color=#39E75F><b>HIGH</b></color>\n" +
                                     $"• AI Confidence: <color=#F2B84B><b>82%</b></color>\n\n" +
                                     $"<i>Operator decision prioritizes life-safety emergency clearance over general traffic delay. Human approval required.</i>";
            }

            // Animated pop-in
            if (_rect != null && _cg != null)
                StartCoroutine(UIAnimator.PopIn(_rect, _cg, 0.25f));
        }

        private void OnContinueClicked()
        {
            SoundManager.Instance?.PlayApprove();
            ScorePopupFX.ShowPopup("+200 PTS — RESPONSIBLE AI HUMAN OVERRIDE!", new Vector2(0, 120), BlueChoice);
            if (modalRoot != null && _cg != null)
                StartCoroutine(HideAndApprove());
            else
            {
                if (modalRoot != null) modalRoot.SetActive(false);
                EventBus.RaiseApproved();
            }
        }

        private IEnumerator HideAndApprove()
        {
            yield return UIAnimator.FadeOut(_cg, 0.18f);
            if (modalRoot != null) modalRoot.SetActive(false);
            EventBus.RaiseApproved();
        }

        private void OnReconsiderClicked()
        {
            SoundManager.Instance?.PlayReject();
            if (modalRoot != null && _cg != null)
                StartCoroutine(HideAndReconsider());
            else
            {
                if (modalRoot != null) modalRoot.SetActive(false);
                GameManager.Instance?.SetState(GameState.Decision);
            }
        }

        private IEnumerator HideAndReconsider()
        {
            yield return UIAnimator.FadeOut(_cg, 0.18f);
            if (modalRoot != null) modalRoot.SetActive(false);
            GameManager.Instance?.SetState(GameState.Decision);
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using NexusTwin.Core;

namespace NexusTwin.UI
{
    /// <summary>
    /// CounterfactualCardPanel — Polished 4-future Digital Twin comparison panel.
    /// Features: Staggered card pop-in animation, color-coded metric deltas (green/red),
    /// AI-recommended card highlighted with glowing border and pulsing badge,
    /// animated best-card reveal sequence.
    /// </summary>
    public class CounterfactualCardPanel : MonoBehaviour
    {
        [Header("Containers")]
        public GameObject panelRoot;
        public Transform cardsContainer;
        public Text summaryHeader;

        [Header("Card Texts (Fallback / Static binding)")]
        public Text card1Title;
        public Text card1Metrics;
        public Image card1Border;

        public Text card2Title;
        public Text card2Metrics;
        public Image card2Border;

        public Text card3Title;
        public Text card3Metrics;
        public Image card3Border;

        public Text card4Title;
        public Text card4Metrics;
        public Image card4Border;

        public Color bestGreenColor    = new Color(0.223f, 0.906f, 0.372f); // #39E75F
        public Color dangerRedColor    = new Color(0.85f, 0.25f, 0.18f);
        public Color warningAmberColor = new Color(0.95f, 0.72f, 0.15f);
        public Color defaultBorderColor = new Color(0.75f, 0.78f, 0.82f);
        public Color neutralGrey       = new Color(0.88f, 0.90f, 0.93f);

        // Card inner image references for glow pulse on best
        private Image[] _cardInnerBgs;
        private RectTransform[] _cardRects;
        private CanvasGroup _panelCg;

        private void Awake()
        {
            _panelCg = panelRoot != null ? panelRoot.GetComponent<CanvasGroup>() : null;
            if (panelRoot != null && _panelCg == null) _panelCg = panelRoot.AddComponent<CanvasGroup>();
        }

        private void Start()
        {
            EventBus.OnSimulationComplete += DisplayResults;
            if (panelRoot != null) panelRoot.SetActive(false);
        }

        private void OnDestroy()
        {
            EventBus.OnSimulationComplete -= DisplayResults;
        }

        public void DisplayResults(ScenarioResultData[] results)
        {
            if (panelRoot == null) return;
            panelRoot.SetActive(true);

            if (summaryHeader != null)
                summaryHeader.text = "DIGITAL TWIN — COUNTERFACTUAL FUTURES";

            if (results == null || results.Length == 0) return;

            var borders = new Image[] { card1Border, card2Border, card3Border, card4Border };
            var titles  = new Text[]  { card1Title,  card2Title,  card3Title,  card4Title  };
            var metrics = new Text[]  { card1Metrics, card2Metrics, card3Metrics, card4Metrics };

            // Collect card rects for staggered pop-in
            _cardRects = new RectTransform[4];
            _cardInnerBgs = new Image[4];
            for (int i = 0; i < 4; i++)
            {
                if (borders[i] != null) _cardRects[i] = borders[i].GetComponent<RectTransform>();
            }

            // Update card content
            for (int i = 0; i < 4 && i < results.Length; i++)
            {
                var r = results[i];
                if (titles[i] != null)
                {
                    titles[i].text = r.label;
                    titles[i].fontStyle = r.isBest ? FontStyle.Bold : FontStyle.Normal;
                }

                if (metrics[i] != null)
                    metrics[i].text = BuildMetricsText(r);

                if (borders[i] != null)
                    borders[i].color = r.isBest ? bestGreenColor : defaultBorderColor;
            }

            // Animate entrance
            StartCoroutine(StaggeredCardEntrance(results));
        }

        private string BuildMetricsText(ScenarioResultData r)
        {
            // Color-coded with rich prefix indicators
            string delayStr   = r.delayDeltaPct   <= 0f ? $"▼ {Mathf.Abs(r.delayDeltaPct):F1}% delay"   : $"▲ {r.delayDeltaPct:F1}% delay";
            string queueStr   = r.queueDeltaPct   <= 0f ? $"▼ {Mathf.Abs(r.queueDeltaPct):F1}% queue"   : $"▲ {r.queueDeltaPct:F1}% queue";
            string emergStr   = r.emergencyDelayS  <= 0f ? $"▼ {Mathf.Abs(r.emergencyDelayS):F0}s ETA"   : $"▲ {r.emergencyDelayS:F0}s ETA";
            string emissStr   = r.emissionsDeltaPct <= 0f ? $"▼ {Mathf.Abs(r.emissionsDeltaPct):F1}% CO₂" : $"▲ {r.emissionsDeltaPct:F1}% CO₂";

            return $"{delayStr}\n{queueStr}\n{emergStr}\n{emissStr}";
        }

        private IEnumerator StaggeredCardEntrance(ScenarioResultData[] results)
        {
            // Fade in panel header first
            if (_panelCg != null)
            {
                _panelCg.alpha = 0f;
                float t = 0f;
                while (t < 0.15f) { t += Time.deltaTime; _panelCg.alpha = t / 0.15f; yield return null; }
                _panelCg.alpha = 1f;
            }

            // Stagger each card pop-in
            var borders = new Image[] { card1Border, card2Border, card3Border, card4Border };
            for (int i = 0; i < 4 && i < results.Length; i++)
            {
                if (_cardRects[i] != null)
                {
                    CanvasGroup cardCg = borders[i]?.gameObject.GetComponent<CanvasGroup>();
                    if (cardCg == null && borders[i] != null) cardCg = borders[i].gameObject.AddComponent<CanvasGroup>();
                    StartCoroutine(UIAnimator.PopIn(_cardRects[i], cardCg, 0.20f));
                }
                yield return new WaitForSeconds(0.08f); // stagger delay
            }

            // After all cards are in, pulse the best card
            yield return new WaitForSeconds(0.3f);
            for (int i = 0; i < 4 && i < results.Length; i++)
            {
                if (results[i].isBest && borders[i] != null)
                {
                    StartCoroutine(UIAnimator.PulseHighlight(borders[i], Color.white, 0.35f, 3));
                    break;
                }
            }
        }

        public void Hide()
        {
            if (panelRoot == null) return;
            if (_panelCg != null)
                StartCoroutine(HideRoutine());
            else
                panelRoot.SetActive(false);
        }

        private IEnumerator HideRoutine()
        {
            yield return UIAnimator.FadeOut(_panelCg, 0.18f);
            panelRoot.SetActive(false);
        }
    }
}

using UnityEngine;
using UnityEngine.UI;
using NexusTwin.Core;
using NexusTwin.Data;

namespace NexusTwin.UI
{
    /// <summary>
    /// DecisionButtons — Human-in-the-loop operator controls: Approve, Reject, Try Another.
    /// Implements Phase G specifications.
    /// </summary>
    public class DecisionButtons : MonoBehaviour
    {
        [Header("Containers")]
        public GameObject panelRoot;

        [Header("Buttons")]
        public Button approveButton;
        public Button rejectButton;
        public Button tryAnotherButton;

        private void Start()
        {
            if (approveButton != null) approveButton.onClick.AddListener(OnApproveClicked);
            if (rejectButton != null) rejectButton.onClick.AddListener(OnRejectClicked);
            if (tryAnotherButton != null) tryAnotherButton.onClick.AddListener(OnTryAnotherClicked);

            EventBus.OnGameStateChanged += HandleGameStateChanged;
            if (panelRoot != null) panelRoot.SetActive(false);
        }

        private void OnDestroy()
        {
            EventBus.OnGameStateChanged -= HandleGameStateChanged;
        }

        private void HandleGameStateChanged(GameState state)
        {
            if (panelRoot == null) return;
            // Only show decision buttons when in Approval or Decision states
            bool shouldShow = (state == GameState.Approval || state == GameState.Explanation);
            panelRoot.SetActive(shouldShow);
        }

        private void OnApproveClicked()
        {
            Debug.Log("[DecisionButtons] Player clicked APPROVE");
            EventBus.RaiseApproved();
            if (panelRoot != null) panelRoot.SetActive(false);
        }

        private void OnRejectClicked()
        {
            Debug.Log("[DecisionButtons] Player clicked REJECT");
            EventBus.RaiseRejected();
            if (panelRoot != null) panelRoot.SetActive(false);
        }

        private void OnTryAnotherClicked()
        {
            Debug.Log("[DecisionButtons] Player clicked TRY ANOTHER");
            GameManager.Instance?.SetState(GameState.Decision);
        }
    }
}

using System.Collections;
using UnityEngine;
using UnityEngine.UI;
using NexusTwin.Core;

namespace NexusTwin.UI
{
    /// <summary>
    /// ExplanationPanel — Polished Explainable AI rationale panel.
    /// Features: typewriter reveal of XAI text, confidence bar with animation,
    /// color-coded confidence (green/amber/red), slide-in entrance animation.
    /// </summary>
    public class ExplanationPanel : MonoBehaviour
    {
        [Header("Containers")]
        public GameObject panelRoot;
        public Image panelBg;
        public Image accentBar;
        public Image confidenceBarFill;

        [Header("Text Fields")]
        public Text actionText;
        public Text reasonText;
        public Text evidenceText;
        public Text confidenceText;
        public Text panelHeader;

        private static readonly Color HighConfColor = new Color(0.22f, 0.78f, 0.40f);
        private static readonly Color MidConfColor  = new Color(0.95f, 0.72f, 0.15f);
        private static readonly Color LowConfColor  = new Color(0.85f, 0.25f, 0.18f);

        private CanvasGroup _cg;
        private RectTransform _rect;

        private void Awake()
        {
            _cg   = panelRoot != null ? panelRoot.GetComponent<CanvasGroup>() : null;
            _rect = panelRoot != null ? panelRoot.GetComponent<RectTransform>() : null;
            if (panelRoot != null && _cg == null) _cg = panelRoot.AddComponent<CanvasGroup>();
        }

        private void Start()
        {
            EventBus.OnExplanationReady += DisplayExplanation;
            if (panelRoot != null) panelRoot.SetActive(false);
        }

        private void OnDestroy()
        {
            EventBus.OnExplanationReady -= DisplayExplanation;
        }

        public void DisplayExplanation(ExplanationData explanation)
        {
            if (panelRoot == null) return;
            panelRoot.SetActive(true);

            if (panelHeader != null) panelHeader.text = "NEXUS-AI EXPLANATION";

            // Color confidence
            Color confColor = explanation.confidence >= 0.80f ? HighConfColor :
                              explanation.confidence >= 0.55f ? MidConfColor  :
                                                               LowConfColor;

            if (actionText != null)
                actionText.text = $"ACTION\n{explanation.action}";
            if (reasonText != null)
                reasonText.text = $"WHY\n{explanation.reason}";
            if (evidenceText != null)
                evidenceText.text = $"EVIDENCE\n{explanation.evidence}";
            if (confidenceText != null)
            {
                confidenceText.text = $"CONFIDENCE: {Mathf.RoundToInt(explanation.confidence * 100f)}%";
                confidenceText.color = confColor;
            }
            if (accentBar != null) accentBar.color = confColor;

            // Animate
            if (_rect != null && _cg != null)
                StartCoroutine(UIAnimator.SlideInFromBottom(_rect, _cg, 20f, 0.25f));
            if (confidenceBarFill != null)
                StartCoroutine(AnimateConfidenceBar(explanation.confidence, confColor));
        }

        private IEnumerator AnimateConfidenceBar(float target, Color col)
        {
            if (confidenceBarFill == null) yield break;
            RectTransform rt = confidenceBarFill.GetComponent<RectTransform>();
            if (rt == null) yield break;
            confidenceBarFill.color = col;
            float t = 0f;
            float duration = 0.5f;
            while (t < duration)
            {
                t += Time.deltaTime;
                float pct = Mathf.SmoothStep(0f, target, t / duration);
                rt.anchorMax = new Vector2(pct, rt.anchorMax.y);
                yield return null;
            }
            rt.anchorMax = new Vector2(target, rt.anchorMax.y);
        }

        public void Hide()
        {
            if (panelRoot == null) return;
            if (_cg != null)
                StartCoroutine(HideRoutine());
            else
                panelRoot.SetActive(false);
        }

        private IEnumerator HideRoutine()
        {
            yield return UIAnimator.FadeOut(_cg, 0.18f);
            panelRoot.SetActive(false);
        }
    }
}

using UnityEngine;
using UnityEngine.UI;
using NexusTwin.Core;
using NexusTwin.Audio;
