using System.Collections;
using UnityEngine;
using UnityEngine.UI;
using NexusTwin.Core;
using NexusTwin.Audio;
using NexusTwin.Data;

namespace NexusTwin.UI
{
    /// <summary>
    /// MissionBriefingPanel — Polished mission briefing screen.
    /// Features: animated entrance, typewriter situation text, pulsing threat badge,
    /// and SPACE/ENTER to start. Supports Mission 01 and 02.
    /// </summary>
    public class MissionBriefingPanel : MonoBehaviour
    {
        public GameObject panelRoot;
        public Text missionTitleText;
        public Text situationText;
        public Text objectiveText;
        public Text threatLevelText;
        public Button startMissionButton;
        public Image threatBadgeImage;

        // Animation
        private CanvasGroup _cg;
        private RectTransform _rect;
        private bool _briefingActive = false;

        private static readonly Color ThreatCritical = new Color(0.85f, 0.25f, 0.18f);
        private static readonly Color ThreatAdvanced = new Color(0.95f, 0.72f, 0.15f);

        private void Awake()
        {
            _cg   = panelRoot != null ? panelRoot.GetComponent<CanvasGroup>() : null;
            _rect = panelRoot != null ? panelRoot.GetComponent<RectTransform>() : null;
            if (panelRoot != null && _cg == null) _cg = panelRoot.AddComponent<CanvasGroup>();
        }

        private void Start()
        {
            if (startMissionButton != null)
                startMissionButton.onClick.AddListener(OnStartMissionClicked);
            EventBus.OnGameStateChanged += HandleGameStateChanged;
        }

        private void OnDestroy()
        {
            EventBus.OnGameStateChanged -= HandleGameStateChanged;
        }

        private void Update()
        {
            if (_briefingActive)
            {
                if (Input.GetKeyDown(KeyCode.Space) || Input.GetKeyDown(KeyCode.Return))
                    OnStartMissionClicked();
            }
        }

        public void SetupBriefing(int missionIndex)
        {
            if (missionIndex == 2)
            {
                if (missionTitleText != null)
                    missionTitleText.text = "MISSION 02: THE ESCAPE CORRIDOR";
                if (threatLevelText != null)
                    threatLevelText.text = "⚠  THREAT: ADVANCED — MULTIPLE EVENTS";
                if (threatBadgeImage != null)
                    threatBadgeImage.color = ThreatAdvanced;
                if (situationText != null)
                    situationText.text = "SITUATION\nDownstream traffic density rising rapidly. Secondary lane disruption near J3. Emergency vehicle crossing under conflicting constraints.";
                if (objectiveText != null)
                    objectiveText.text = "OBJECTIVE\nCoordinate corridor optimization vs direct Emergency Priority. Minimize delay while keeping ambulance transit within safety margins. Human approval required.";
            }
            else
            {
                if (missionTitleText != null)
                    missionTitleText.text = "MISSION 01: CLEAR THE EMERGENCY CORRIDOR";
                if (threatLevelText != null)
                    threatLevelText.text = "⚠  THREAT: CRITICAL — SIGNAL COMPROMISED";
                if (threatBadgeImage != null)
                    threatBadgeImage.color = ThreatCritical;
                if (situationText != null)
                    situationText.text = "SITUATION\nDeliberate traffic disruption detected at Junction J2. Signal tampering confirmed. Critical trauma ambulance (AMBULANCE_01) is en route. ETA: 4 minutes.";
                if (objectiveText != null)
                    objectiveText.text = "OBJECTIVE\nDeploy an AI-assisted adaptive traffic intervention. Evaluate Digital Twin counterfactual futures. Prevent gridlock. Secure zero-delay transit for the emergency vehicle.\n\n[SPACE] or [ENTER] to deploy →";
            }
        }

        private void HandleGameStateChanged(GameState state)
        {
            bool show = (state == GameState.Briefing);
            _briefingActive = show;

            if (show)
            {
                SetupBriefing(GameManager.Instance != null ? GameManager.Instance.currentMission : 1);
                if (panelRoot != null) panelRoot.SetActive(true);
                if (_rect != null && _cg != null)
                    StartCoroutine(UIAnimator.PopIn(_rect, _cg, 0.28f));
                if (threatBadgeImage != null)
                    StartCoroutine(UIAnimator.PulseHighlight(threatBadgeImage, Color.white, 0.5f, 4));
            }
            else
            {
                _briefingActive = false;
                if (panelRoot != null && _cg != null)
                    StartCoroutine(HideRoutine());
                else if (panelRoot != null)
                    panelRoot.SetActive(false);
            }
        }

        private IEnumerator HideRoutine()
        {
            yield return UIAnimator.FadeOut(_cg, 0.20f);
            if (panelRoot != null) panelRoot.SetActive(false);
        }

        private void OnStartMissionClicked()
        {
            if (!_briefingActive) return;
            _briefingActive = false;
            SoundManager.Instance?.PlayClick();
            if (panelRoot != null && _cg != null)
                StartCoroutine(StartTransition());
            else
            {
                if (panelRoot != null) panelRoot.SetActive(false);
                GameManager.Instance?.SetState(GameState.Idle);
            }
        }

        private IEnumerator StartTransition()
        {
            yield return UIAnimator.FadeOut(_cg, 0.22f);
            if (panelRoot != null) panelRoot.SetActive(false);
            GameManager.Instance?.SetState(GameState.Idle);
        }
    }
}

using System.Collections;
using UnityEngine;
using UnityEngine.UI;
using NexusTwin.Core;
using NexusTwin.Audio;
using NexusTwin.Data;
using NexusTwin.Gameplay;

namespace NexusTwin.UI
{
    /// <summary>
    /// ScoreDebriefPanel — Phase E Responsible AI Decision Replay & Outcome Comparison.
    /// Features:
    /// - Decision Replay (Player Choice vs AI Recommendation)
    /// - Predicted vs Actual outcome comparison table:
    ///   * Network Delay:   Predicted -37% | Actual -32%
    ///   * Peak Queue:      Predicted -30% | Actual -27%
    ///   * Ambulance ETA:   Predicted -31s | Actual -29s
    ///   * Safety Rating:   Predicted HIGH | Actual HIGH
    /// - Responsible AI Rationale text validating human oversight.
    /// </summary>
    public class ScoreDebriefPanel : MonoBehaviour
    {
        public static ScoreDebriefPanel Instance { get; private set; }

        public GameObject panelRoot;
        public Text titleText;
        public Text totalScoreText;
        public Text breakdownText;
        public Text comparisonText;
        public Text decisionReplayText;
        public Button replayButton;
        public Button nextMissionButton;

        private CanvasGroup _cg;
        private RectTransform _rect;

        private void Awake()
        {
            if (Instance != null && Instance != this) { Destroy(gameObject); return; }
            Instance = this;

            _cg   = panelRoot != null ? panelRoot.GetComponent<CanvasGroup>() : null;
            _rect = panelRoot != null ? panelRoot.GetComponent<RectTransform>() : null;
            if (panelRoot != null && _cg == null) _cg = panelRoot.AddComponent<CanvasGroup>();
        }

        private void Start()
        {
            if (replayButton != null)
                replayButton.onClick.AddListener(OnReplayClicked);
            if (nextMissionButton != null)
                nextMissionButton.onClick.AddListener(OnNextMissionClicked);

            EventBus.OnScenarioComplete += ShowDebrief;
            EventBus.OnGameStateChanged += HandleGameStateChanged;
            if (panelRoot != null) panelRoot.SetActive(false);
        }

        private void OnDestroy()
        {
            EventBus.OnScenarioComplete -= ShowDebrief;
            EventBus.OnGameStateChanged -= HandleGameStateChanged;
        }

        private void HandleGameStateChanged(GameState state)
        {
            if (panelRoot != null)
            {
                panelRoot.SetActive(state == GameState.Score);
            }
        }

        public void ShowDebrief(ScoreBreakdownData score)
        {
            if (panelRoot == null) return;
            panelRoot.SetActive(true);
            SoundManager.Instance?.PlayFanfare();

            int mission = (GameManager.Instance != null) ? GameManager.Instance.currentMission : 1;
            StrategyType playerStrategy = (ScenarioDirector.Instance != null) ? ScenarioDirector.Instance.selectedStrategy.type : StrategyType.EmergencyPriority;
            string playerChoiceStr = playerStrategy == StrategyType.Diversion ? "Divert Traffic" :
                                    playerStrategy == StrategyType.EmergencyPriority ? "Emergency Priority" :
                                    playerStrategy == StrategyType.GreenExtend ? "Extend Green" : "Do Nothing";

            if (titleText != null)
                titleText.text = $"MISSION 0{mission} COMPLETE — RESPONSIBLE AI DEBRIEF";

            if (totalScoreText != null)
                totalScoreText.text = $"{score.Total} / 1000 PTS";

            if (breakdownText != null)
            {
                breakdownText.text = $"• Traffic Efficiency: <b>{score.trafficFlow} pts</b>\n" +
                                     $"• Emergency Safety: <b>{score.emergencySafety} pts</b>\n" +
                                     $"• Queue Control:    <b>{score.queueControl} pts</b>\n" +
                                     $"• AI Alignment:     <b>{score.decisionQuality} pts</b>";
            }

            // ── PHASE E: DECISION REPLAY & PREDICTED VS ACTUAL ─────────────
            if (comparisonText != null)
            {
                bool isOverride = (playerStrategy != StrategyType.Diversion);

                string rationale = isOverride
                    ? "<i>Your decision differed from AI recommendation — but successfully protected the emergency corridor under human oversight.</i>"
                    : "<i>Accepted AI recommendation. Optimal balance achieved between network delay and emergency clearance.</i>";

                comparisonText.text =
                    $"<b>DECISION REPLAY:</b>\n" +
                    $"• YOUR DECISION: <color=#1A87D4><b>{playerChoiceStr.ToUpper()}</b></color>  │  AI RECOMMENDATION: <color=#39E75F><b>DIVERT TRAFFIC</b></color>\n\n" +
                    $"<b>OUTCOME COMPARISON:</b>\n" +
                    $"  METRIC              PREDICTED      ACTUAL\n" +
                    $"  ──────────────────────────────────────────\n" +
                    $"  Network Delay        -37.6%        -32.4%\n" +
                    $"  Peak Queue           -30.1%        -27.5%\n" +
                    $"  Ambulance ETA        -31.0s        -29.2s\n" +
                    $"  Safety Rating         HIGH          HIGH\n\n" +
                    $"{rationale}";
            }

            // Animated pop-in
            if (_rect != null && _cg != null)
                StartCoroutine(UIAnimator.PopIn(_rect, _cg, 0.28f));
        }

        private void OnReplayClicked()
        {
            SoundManager.Instance?.PlayClick();
            if (panelRoot != null) panelRoot.SetActive(false);
            EventBus.RaiseMissionRestart();
        }

        private void OnNextMissionClicked()
        {
            SoundManager.Instance?.PlayClick();
            if (GameManager.Instance != null)
            {
                GameManager.Instance.currentMission = (GameManager.Instance.currentMission == 1) ? 2 : 1;
            }
            if (panelRoot != null) panelRoot.SetActive(false);
            EventBus.RaiseMissionRestart();
        }
    }
}

using System.Collections;
using UnityEngine;
using UnityEngine.UI;

namespace NexusTwin.UI
{
    /// <summary>
    /// ScorePopupFX — Floating score popup feedback for rewarding human choices.
    /// Spawns animated text ("+150 PTS — AI ALIGNMENT!") that floats up and fades out.
    /// </summary>
    public class ScorePopupFX : MonoBehaviour
    {
        public static ScorePopupFX Instance { get; private set; }

        private Transform _canvasTransform;
        private Font _font;

        private void Awake()
        {
            if (Instance != null && Instance != this) { Destroy(gameObject); return; }
            Instance = this;
        }

        private void Start()
        {
            HUDController hud = HUDController.Instance;
            if (hud != null) _canvasTransform = hud.transform;
            _font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf") ?? Resources.GetBuiltinResource<Font>("Arial.ttf");
        }

        public static void ShowPopup(string text, Vector2 screenPos, Color color)
        {
            if (Instance == null) return;
            Instance.Spawn(text, screenPos, color);
        }

        private void Spawn(string text, Vector2 pos, Color color)
        {
            if (_canvasTransform == null)
            {
                HUDController hud = HUDController.Instance;
                if (hud != null) _canvasTransform = hud.transform;
                else return;
            }

            GameObject popupObj = new GameObject("ScorePopup");
            popupObj.transform.SetParent(_canvasTransform, false);
            RectTransform rect = popupObj.AddComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot     = new Vector2(0.5f, 0.5f);
            rect.anchoredPosition = pos;
            rect.sizeDelta = new Vector2(400, 50);

            Text t = popupObj.AddComponent<Text>();
            t.text = text;
            t.font = _font;
            t.fontSize = 18;
            t.fontStyle = FontStyle.Bold;
            t.color = color;
            t.alignment = TextAnchor.MiddleCenter;

            CanvasGroup cg = popupObj.AddComponent<CanvasGroup>();
            StartCoroutine(AnimatePopup(rect, cg));
        }

        private IEnumerator AnimatePopup(RectTransform rect, CanvasGroup cg)
        {
            Vector2 startPos = rect.anchoredPosition;
            Vector2 endPos   = startPos + new Vector2(0f, 60f);

            float duration = 1.2f;
            float time = 0f;

            while (time < duration)
            {
                time += Time.deltaTime;
                float pct = time / duration;

                rect.anchoredPosition = Vector2.Lerp(startPos, endPos, pct);
                cg.alpha = Mathf.Lerp(1f, 0f, pct * pct);

                yield return null;
            }

            Destroy(rect.gameObject);
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using NexusTwin.Core;
using NexusTwin.Data;

namespace NexusTwin.UI
{
    /// <summary>
    /// StrategyPanel — Polished strategy selection panel with animated entrance,
    /// hover-glow button states, selection confirmation animation, and
    /// AI recommendation badge highlighting.
    /// </summary>
    public class StrategyPanel : MonoBehaviour
    {
        [Header("Containers")]
        public GameObject panelRoot;
        public Transform optionsContainer;
        public Button simulateButton;
        public Text selectedStrategyLabel;
        public Text panelTitleText;

        // Color palette
        private static readonly Color ActiveBlueDark = new Color(0.08f, 0.46f, 0.78f);
        private static readonly Color AIRecommendGreen = new Color(0.223f, 0.906f, 0.372f);
        private static readonly Color DefaultBtn  = new Color(0.88f, 0.90f, 0.93f);
        private static readonly Color NavyText    = new Color(0.06f, 0.08f, 0.12f);
        private static readonly Color InactiveBtn = new Color(0.22f, 0.26f, 0.34f);

        private List<StrategyOptionData> _currentOptions = new List<StrategyOptionData>();
        private StrategyOptionData _selectedOption;
        private List<Button> _spawnedButtons = new List<Button>();
        private CanvasGroup _panelCg;
        private RectTransform _panelRect;

        private void Awake()
        {
            _panelCg = panelRoot != null ? panelRoot.GetComponent<CanvasGroup>() : null;
            if (panelRoot != null && _panelCg == null) _panelCg = panelRoot.AddComponent<CanvasGroup>();
            _panelRect = panelRoot != null ? panelRoot.GetComponent<RectTransform>() : null;
        }

        private void Start()
        {
            EventBus.OnStrategiesReady += HandleStrategiesReady;
            if (simulateButton != null) simulateButton.onClick.AddListener(OnSimulateClicked);
            if (panelRoot != null) panelRoot.SetActive(false);
        }

        private void OnDestroy()
        {
            EventBus.OnStrategiesReady -= HandleStrategiesReady;
        }

        public void HandleStrategiesReady(StrategyOptionData[] options)
        {
            if (panelRoot == null) return;
            panelRoot.SetActive(true);

            // Clear previous
            foreach (var btn in _spawnedButtons)
                if (btn != null) Destroy(btn.gameObject);
            _spawnedButtons.Clear();

            _currentOptions = new List<StrategyOptionData>(options);

            if (panelTitleText != null)
                panelTitleText.text = "SELECT INTERVENTION STRATEGY";

            if (optionsContainer != null)
            {
                for (int i = 0; i < _currentOptions.Count; i++)
                {
                    int index = i;
                    var opt = _currentOptions[i];
                    bool isAIRecommended = (opt.type == StrategyType.Diversion);

                    // Outer button container
                    GameObject btnObj = new GameObject($"StratBtn_{index}");
                    btnObj.transform.SetParent(optionsContainer, false);
                    RectTransform rect = btnObj.AddComponent<RectTransform>();
                    rect.anchorMin = new Vector2(0.5f, 1);
                    rect.anchorMax = new Vector2(0.5f, 1);
                    rect.pivot = new Vector2(0.5f, 1);
                    rect.sizeDelta = new Vector2(340, 36);
                    rect.anchoredPosition = new Vector2(0, -index * 42);

                    // Background image
                    Image img = btnObj.AddComponent<Image>();
                    img.color = InactiveBtn;

                    // Left accent strip
                    GameObject strip = new GameObject("AccentStrip");
                    strip.transform.SetParent(btnObj.transform, false);
                    RectTransform stripRect = strip.AddComponent<RectTransform>();
                    stripRect.anchorMin = new Vector2(0, 0);
                    stripRect.anchorMax = new Vector2(0, 1);
                    stripRect.sizeDelta = new Vector2(4, 0);
                    stripRect.anchoredPosition = Vector2.zero;
                    Image stripImg = strip.AddComponent<Image>();
                    stripImg.color = isAIRecommended ? AIRecommendGreen : new Color(0.35f, 0.40f, 0.50f);

                    Button btn = btnObj.AddComponent<Button>();
                    _spawnedButtons.Add(btn);

                    // Main label
                    GameObject labelObj = new GameObject("Label");
                    labelObj.transform.SetParent(btnObj.transform, false);
                    RectTransform lblRect = labelObj.AddComponent<RectTransform>();
                    lblRect.anchorMin = new Vector2(0.02f, 0);
                    lblRect.anchorMax = new Vector2(0.78f, 1);
                    lblRect.sizeDelta = Vector2.zero;
                    Text t = labelObj.AddComponent<Text>();
                    t.text = opt.label;
                    t.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf") ?? Resources.GetBuiltinResource<Font>("Arial.ttf");
                    t.fontSize = 12;
                    t.fontStyle = FontStyle.Normal;
                    t.color = Color.white;
                    t.alignment = TextAnchor.MiddleLeft;

                    // AI badge for recommended strategy
                    if (isAIRecommended)
                    {
                        GameObject badge = new GameObject("AIBadge");
                        badge.transform.SetParent(btnObj.transform, false);
                        RectTransform badgeRect = badge.AddComponent<RectTransform>();
                        badgeRect.anchorMin = new Vector2(0.80f, 0.15f);
                        badgeRect.anchorMax = new Vector2(0.99f, 0.85f);
                        badgeRect.sizeDelta = Vector2.zero;
                        Image badgeBg = badge.AddComponent<Image>();
                        badgeBg.color = AIRecommendGreen;
                        Text badgeText = badge.AddComponent<Text>();
                        badgeText.text = "AI ★";
                        badgeText.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
                        badgeText.fontSize = 10;
                        badgeText.fontStyle = FontStyle.Bold;
                        badgeText.color = new Color(0.04f, 0.08f, 0.04f);
                        badgeText.alignment = TextAnchor.MiddleCenter;
                    }

                    btn.onClick.AddListener(() => SelectOption(opt));
                }
            }

            if (_currentOptions.Count > 0) SelectOption(_currentOptions[0]);

            // Animate entrance
            if (_panelRect != null && _panelCg != null)
                StartCoroutine(UIAnimator.SlideInFromRight(_panelRect, _panelCg, 30f, 0.25f));
        }

        public void SelectOption(StrategyOptionData option)
        {
            _selectedOption = option;
            if (selectedStrategyLabel != null)
                selectedStrategyLabel.text = $"▶  {option.label}";

            for (int i = 0; i < _currentOptions.Count; i++)
            {
                if (i >= _spawnedButtons.Count || _spawnedButtons[i] == null) continue;
                Image img = _spawnedButtons[i].GetComponent<Image>();
                Text txt = _spawnedButtons[i].GetComponentInChildren<Text>();
                bool isSelected = (_currentOptions[i].type == option.type);

                if (isSelected)
                {
                    img.color = ActiveBlueDark;
                    if (txt != null) txt.color = Color.white;
                    if (txt != null) txt.fontStyle = FontStyle.Bold;
                    StartCoroutine(SelectionFlash(img));
                }
                else
                {
                    img.color = InactiveBtn;
                    if (txt != null) txt.color = new Color(0.80f, 0.82f, 0.85f);
                    if (txt != null) txt.fontStyle = FontStyle.Normal;
                }
            }

            EventBus.RaiseStrategySelected(option);
        }

        private IEnumerator SelectionFlash(Image img)
        {
            Color flash = Color.white;
            Color target = ActiveBlueDark;
            float t = 0f;
            while (t < 0.12f)
            {
                t += Time.deltaTime;
                img.color = Color.Lerp(flash, target, t / 0.12f);
                yield return null;
            }
            img.color = target;
        }

        private void OnSimulateClicked()
        {
            if (simulateButton != null)
                StartCoroutine(ButtonClickFeedback(simulateButton.GetComponent<Image>()));
            Debug.Log("[StrategyPanel] SIMULATE triggered by player");
            EventBus.RaiseSimulateRequested();
        }

        private IEnumerator ButtonClickFeedback(Image img)
        {
            if (img == null) yield break;
            Color orig = img.color;
            img.color = Color.white;
            yield return new WaitForSeconds(0.08f);
            img.color = orig;
        }

        public void Hide()
        {
            if (panelRoot == null) return;
            if (_panelCg != null)
                StartCoroutine(HideRoutine());
            else
                panelRoot.SetActive(false);
        }

        private IEnumerator HideRoutine()
        {
            yield return UIAnimator.FadeOut(_panelCg, 0.18f);
            panelRoot.SetActive(false);
        }
    }
}

using System.Collections;
using UnityEngine;
using UnityEngine.UI;

namespace NexusTwin.UI
{
    /// <summary>
    /// UIAnimator — Provides smooth, polished UI transitions for all NEXUS-TWIN panels.
    /// Supports fade-in/out, slide-from-top, slide-from-bottom, slide-from-right,
    /// scale pop-in, and pulsing highlight. All animations use consistent easing curves
    /// matching the NEXUS-TWIN design language (fast in, gentle easeOut).
    /// </summary>
    public static class UIAnimator
    {
        // ─────────────────────────────────────────────────────────────────────────
        // Fade
        // ─────────────────────────────────────────────────────────────────────────
        public static IEnumerator FadeIn(CanvasGroup cg, float duration = 0.25f, System.Action onComplete = null)
        {
            if (cg == null) yield break;
            cg.alpha = 0f;
            cg.interactable = false;
            cg.blocksRaycasts = false;
            float t = 0f;
            while (t < duration)
            {
                t += Time.deltaTime;
                cg.alpha = Mathf.SmoothStep(0f, 1f, t / duration);
                yield return null;
            }
            cg.alpha = 1f;
            cg.interactable = true;
            cg.blocksRaycasts = true;
            onComplete?.Invoke();
        }

        public static IEnumerator FadeOut(CanvasGroup cg, float duration = 0.20f, System.Action onComplete = null)
        {
            if (cg == null) yield break;
            cg.interactable = false;
            cg.blocksRaycasts = false;
            float startAlpha = cg.alpha;
            float t = 0f;
            while (t < duration)
            {
                t += Time.deltaTime;
                cg.alpha = Mathf.SmoothStep(startAlpha, 0f, t / duration);
                yield return null;
            }
            cg.alpha = 0f;
            onComplete?.Invoke();
        }

        // ─────────────────────────────────────────────────────────────────────────
        // Slide + Fade (directional entrance)
        // ─────────────────────────────────────────────────────────────────────────
        public static IEnumerator SlideInFromTop(RectTransform rect, CanvasGroup cg, float slideDistance = 30f, float duration = 0.28f)
        {
            if (rect == null) yield break;
            Vector2 endPos = rect.anchoredPosition;
            Vector2 startPos = endPos + new Vector2(0f, slideDistance);
            if (cg != null) { cg.alpha = 0f; cg.blocksRaycasts = false; }
            float t = 0f;
            while (t < duration)
            {
                t += Time.deltaTime;
                float pct = EaseOutCubic(t / duration);
                rect.anchoredPosition = Vector2.Lerp(startPos, endPos, pct);
                if (cg != null) cg.alpha = pct;
                yield return null;
            }
            rect.anchoredPosition = endPos;
            if (cg != null) { cg.alpha = 1f; cg.blocksRaycasts = true; }
        }

        public static IEnumerator SlideInFromBottom(RectTransform rect, CanvasGroup cg, float slideDistance = 30f, float duration = 0.28f)
        {
            if (rect == null) yield break;
            Vector2 endPos = rect.anchoredPosition;
            Vector2 startPos = endPos - new Vector2(0f, slideDistance);
            if (cg != null) { cg.alpha = 0f; cg.blocksRaycasts = false; }
            float t = 0f;
            while (t < duration)
            {
                t += Time.deltaTime;
                float pct = EaseOutCubic(t / duration);
                rect.anchoredPosition = Vector2.Lerp(startPos, endPos, pct);
                if (cg != null) cg.alpha = pct;
                yield return null;
            }
            rect.anchoredPosition = endPos;
            if (cg != null) { cg.alpha = 1f; cg.blocksRaycasts = true; }
        }

        public static IEnumerator SlideInFromRight(RectTransform rect, CanvasGroup cg, float slideDistance = 40f, float duration = 0.28f)
        {
            if (rect == null) yield break;
            Vector2 endPos = rect.anchoredPosition;
            Vector2 startPos = endPos + new Vector2(slideDistance, 0f);
            if (cg != null) { cg.alpha = 0f; cg.blocksRaycasts = false; }
            float t = 0f;
            while (t < duration)
            {
                t += Time.deltaTime;
                float pct = EaseOutCubic(t / duration);
                rect.anchoredPosition = Vector2.Lerp(startPos, endPos, pct);
                if (cg != null) cg.alpha = pct;
                yield return null;
            }
            rect.anchoredPosition = endPos;
            if (cg != null) { cg.alpha = 1f; cg.blocksRaycasts = true; }
        }

        // ─────────────────────────────────────────────────────────────────────────
        // Scale Pop-In (used for cards and modals)
        // ─────────────────────────────────────────────────────────────────────────
        public static IEnumerator PopIn(RectTransform rect, CanvasGroup cg, float duration = 0.22f)
        {
            if (rect == null) yield break;
            if (cg != null) { cg.alpha = 0f; cg.blocksRaycasts = false; }
            rect.localScale = new Vector3(0.88f, 0.88f, 1f);
            float t = 0f;
            while (t < duration)
            {
                t += Time.deltaTime;
                float pct = EaseOutBack(t / duration);
                float s = Mathf.Lerp(0.88f, 1f, pct);
                rect.localScale = new Vector3(s, s, 1f);
                if (cg != null) cg.alpha = Mathf.Clamp01(pct);
                yield return null;
            }
            rect.localScale = Vector3.one;
            if (cg != null) { cg.alpha = 1f; cg.blocksRaycasts = true; }
        }

        // ─────────────────────────────────────────────────────────────────────────
        // Pulse Highlight (used on "best" cards and approved state)
        // ─────────────────────────────────────────────────────────────────────────
        public static IEnumerator PulseHighlight(Image target, Color pulseColor, float duration = 0.6f, int pulses = 3)
        {
            if (target == null) yield break;
            Color originalColor = target.color;
            for (int i = 0; i < pulses; i++)
            {
                float t = 0f;
                float half = duration * 0.5f;
                while (t < half) { t += Time.deltaTime; target.color = Color.Lerp(originalColor, pulseColor, t / half); yield return null; }
                t = 0f;
                while (t < half) { t += Time.deltaTime; target.color = Color.Lerp(pulseColor, originalColor, t / half); yield return null; }
            }
            target.color = originalColor;
        }

        // ─────────────────────────────────────────────────────────────────────────
        // Typewriter text (cinematic and alert)
        // ─────────────────────────────────────────────────────────────────────────
        public static IEnumerator Typewriter(Text target, string fullText, float charsPerSecond = 40f)
        {
            if (target == null) yield break;
            target.text = "";
            int len = fullText.Length;
            float delay = 1f / charsPerSecond;
            for (int i = 0; i <= len; i++)
            {
                target.text = fullText.Substring(0, i);
                yield return new WaitForSeconds(delay);
            }
        }

        // ─────────────────────────────────────────────────────────────────────────
        // Easing functions
        // ─────────────────────────────────────────────────────────────────────────
        private static float EaseOutCubic(float t) => 1f - Mathf.Pow(1f - Mathf.Clamp01(t), 3f);

        private static float EaseOutBack(float t)
        {
            float c1 = 1.70158f;
            float c3 = c1 + 1f;
            t = Mathf.Clamp01(t);
            return 1f + c3 * Mathf.Pow(t - 1f, 3f) + c1 * Mathf.Pow(t - 1f, 2f);
        }
    }
}

